-- Extra catalogue strains (researched facts). Idempotent upsert on slug.
on conflict (slug) do update set name = excluded.name, breeder = excluded.breeder, dominance = excluded.dominance, flowering = excluded.flowering,
  flowering_weeks_min = excluded.flowering_weeks_min, flowering_weeks_max = excluded.flowering_weeks_max, description = excluded.description, description_cs = excluded.description_cs;
update public.strains set approved = true where created_by is null;
