insert into public.strains (slug, name, breeder, dominance, flowering, flowering_weeks_min, flowering_weeks_max, description, description_cs) values
('acdc', 'ACDC', 'Various', 'sativa', 'photo', 9, 10, 'High-CBD, low-THC selection that originated as a phenotype of Cannatonic. Moderately vigorous plants with a sativa-leaning structure and medium-density buds; CBD to THC ratio varies between cuts and seed lines, so lab testing is the only way to confirm it. Finishes in roughly nine to ten weeks indoors.', 'Odrůda s vysokým obsahem CBD a nízkým THC, která vznikla jako fenotyp Cannatonicu. Středně vzrůstné rostliny se sativovou stavbou a středně hustými palicemi; poměr CBD a THC se mezi klony a semennými liniemi liší, takže jistotu dá jen laboratorní test. Uvnitř dozrává zhruba za devět až deset týdnů.'),
('afghan-kush-auto', 'Afghan Kush Auto', 'Various', 'indica', 'auto', 6, 8, 'Autoflowering version of Afghan Kush, built on Afghan indica genetics crossed with ruderalis. Plants stay short and compact with broad leaves and dense, resinous buds, which suits small tents and balconies.', 'Samonakvétací verze Afghan Kush postavená na afghánské indice křížené s ruderalis. Rostliny zůstávají nízké a kompaktní, mají široké listy a husté pryskyřičné palice, takže se hodí do malých stanů i na balkon.'),
('agent-orange', 'Agent Orange', 'TGA Subcool Seeds', 'hybrid', 'photo', 8, 9, 'Agent Orange is a TGA Subcool hybrid from Orange Velvet and Jack the Ripper, known for a strong orange-peel aroma. Plants stretch moderately and respond well to topping and training. Buds are dense and often show orange pistils at maturity.', 'Agent Orange je hybrid od TGA Subcool z křížení Orange Velvet a Jack the Ripper, známý výraznou vůní pomerančové kůry. Rostliny se v květu mírně natahují a dobře snášejí zaštipování a tvarování. Palice jsou husté a ke konci často s oranžovými bliznami.'),
('alien-og', 'Alien OG', 'The Cali Connection', 'hybrid', 'photo', 8, 9, 'Alien OG is an OG-type hybrid from Tahoe OG crossed with Alien Kush, popularised by The Cali Connection. Plants stay medium-sized with a fair amount of stretch and build dense, resinous, lime-green colas. Like most OG lines it appreciates good airflow and a stable environment late in flower.', 'Alien OG je hybrid typu OG vzniklý křížením Tahoe OG a Alien Kush, rozšířený díky The Cali Connection. Rostliny jsou středně vysoké s mírným natahováním a tvoří husté, pryskyřičné, limetkově zelené palice. Jako většina OG linií ocení dobré proudění vzduchu a stabilní prostředí v pozdní fázi kvetení.'),
('amnesia-auto', 'Amnesia Auto', 'Various', 'sativa', 'auto', 7, 9, 'Autoflowering version of the Amnesia Haze line, offered by several seedbanks. Plants stay taller and airier than most autos, with long, spear-shaped colas. Benefits from a bright, well-ventilated space and light feeding.', 'Samonakvétací verze linie Amnesia Haze, kterou nabízí více semenáren. Rostliny bývají na autoflower vyšší a vzdušnější, s dlouhými kopinatými palicemi. Dobře se jí daří při silném světle, dobrém větrání a mírném hnojení.'),
('amnesia-lemon', 'Amnesia Lemon', 'Various', 'sativa', 'photo', 10, 11, 'Sativa-dominant Amnesia-line strain selected for a sharp lemon aroma. Expect noticeable stretch after the flip and long, airy-to-medium colas, so training and enough vertical space help. Bloom is on the long side at around ten to eleven weeks.', 'Převážně sativová odrůda z linie Amnesia vyšlechtěná pro výrazné citronové aroma. Po přepnutí na květ se výrazně natahuje a tvoří dlouhé, spíše vzdušné palice, proto pomůže trénink a dostatek prostoru na výšku. Kvetení je delší, zhruba deset až jedenáct týdnů.'),
('animal-cookies', 'Animal Cookies', 'Various', 'indica', 'photo', 9, 10, 'Cookies-family hybrid usually described as Girl Scout Cookies x Fire OG. Medium-height plants with tight, frosty buds that often take on purple tones in cooler night temperatures; yields are moderate.', 'Hybrid z rodiny Cookies, obvykle uváděný jako Girl Scout Cookies x Fire OG. Středně vysoké rostliny s pevnými, ojíněnými palicemi, které při chladnějších nocích často fialoví; výnos je střední.'),
('apple-fritter', 'Apple Fritter', 'Lumpy''s Flowers', 'hybrid', 'photo', 8, 9, 'Apple Fritter is a hybrid from Sour Apple and Animal Cookies, popularised by Lumpy''s Flowers. It grows compact to medium-sized with dense, resin-heavy buds and a sweet, pastry-like aroma. Good airflow helps keep the tight colas healthy late in flower.', 'Apple Fritter je hybrid ze Sour Apple a Animal Cookies, který proslavil Lumpy''s Flowers. Roste kompaktně až středně a tvoří husté, silně pryskyřičnaté palice se sladkou vůní připomínající pečivo. Dobré proudění vzduchu pomáhá udržet husté vrcholy zdravé v pozdním květu.'),
('apples-and-bananas', 'Apples and Bananas', 'Compound Genetics', 'hybrid', 'photo', 9, 10, 'Apples and Bananas is a modern dessert-style hybrid from Compound Genetics. It grows vigorous, fairly compact plants that respond well to topping and training, and finishes with chunky, frosty buds with a fruity aroma. Stronger feeding late in flower is usually well tolerated.', 'Apples and Bananas je moderní dezertní hybrid od Compound Genetics. Roste jako vitální, poměrně kompaktní rostlina, která dobře snáší zaštipování a tvarování, a dozrává do mohutných, ojíněných palic s ovocnou vůní. Silnější hnojení v pozdní fázi kvetení obvykle zvládá bez problémů.'),
('banana-kush', 'Banana Kush', 'Various', 'hybrid', 'photo', 8, 9, 'Californian hybrid known for a sweet, fruity banana aroma. Grows to medium height with dense, resinous buds and responds well to topping and SCROG. Odour control is advisable during late flowering.', 'Kalifornský hybrid známý sladkou ovocnou vůní po banánu. Dorůstá střední výšky s hustými, pryskyřičnými palicemi a dobře snáší zaštipování i SCROG. V pozdním květu se vyplatí řešit pachy.'),
('banana-og', 'Banana OG', 'Various', 'hybrid', 'photo', 8, 9, 'OG Kush-based hybrid known for a sweet banana-like aroma over a gassy OG background. Plants have typical OG structure with moderate stretch and dense, resinous buds that appreciate good airflow. Flowering takes about eight to nine weeks.', 'Hybrid z linie OG Kush, známý sladkou banánovou vůní s typickým OG podtónem. Rostliny mají klasickou OG stavbu se středním natahováním a husté pryskyřičné palice, které ocení dobré proudění vzduchu. Kvetení trvá asi osm až devět týdnů.'),
('berry-white', 'Berry White', 'Various', 'hybrid', 'photo', 8, 9, 'Hybrid of Blueberry and White Widow. Grows as a balanced, medium-sized plant with a heavy trichome coat and a sweet berry aroma; it is considered fairly easy to keep in shape indoors.', 'Kříženec Blueberry a White Widow. Roste jako vyvážená, středně velká rostlina s hustým povlakem trichomů a sladkou bobulovou vůní; v interiéru se dá poměrně snadno udržet ve tvaru.'),
('big-bang', 'Big Bang', 'Green House Seeds', 'hybrid', 'photo', 8, 9, 'Big Bang is a Green House Seeds hybrid built from Skunk, Northern Lights and El Niño genetics. It is a vigorous, fairly easy plant that suits both indoor and outdoor growing. Expect a moderate stretch and compact, resinous colas.', 'Big Bang je hybrid od Green House Seeds postavený na genetice Skunk, Northern Lights a El Niño. Je to vitální a poměrně nenáročná rostlina vhodná pro pěstování uvnitř i venku. Počítej s mírným natažením v květu a kompaktními, pryskyřičnatými vrcholy.'),
('big-bud', 'Big Bud', 'Various', 'indica', 'photo', 7, 9, 'Big Bud is a classic indica-dominant line from the 1980s, known for very large, heavy colas. Branches often need support or a trellis late in flower because of the bud weight. It is a forgiving plant that suits both beginners and sea-of-green setups.', 'Big Bud je klasická indikově dominantní linie z 80. let, známá velmi velkými a těžkými palicemi. Větve v pozdním kvetení kvůli váze často potřebují oporu nebo síť. Je to nenáročná rostlina vhodná pro začátečníky i pro metodu sea of green.'),
('big-devil-auto', 'Big Devil Auto', 'Sweet Seeds', 'hybrid', 'auto', 6, 8, 'Large-yielding autoflower from Sweet Seeds that can grow unusually tall for an auto. Forms a dominant central cola with several strong side branches. Give it a big final pot from the start, since autos don''t recover well from transplant stress.', 'Výnosná samonakvétačka od Sweet Seeds, která na autoflower dorůstá nezvykle vysoko. Tvoří dominantní centrální palici a několik silných postranních větví. Hned od začátku jí dejte velký finální květináč, autoflowery přesazování špatně snášejí.'),
('biscotti', 'Biscotti', 'Cookies', 'indica', 'photo', 9, 10, 'Indica-leaning dessert strain from the Cookies family with Gelato in its background. Compact, bushy plants produce dense, often purple-tinged buds with a sweet, nutty aroma; keep humidity in check late in bloom. Usually ready after nine to ten weeks of flowering.', 'Převážně indická dezertní odrůda z rodiny Cookies s Gelatem v rodokmenu. Kompaktní, košaté rostliny tvoří husté, často do fialova zbarvené palice se sladkou oříškovou vůní; na konci květu je dobré hlídat vlhkost. Obvykle je hotová po devíti až deseti týdnech kvetení.'),
('black-cherry-punch', 'Black Cherry Punch', 'Various', 'indica', 'photo', 8, 9, 'Indica-leaning modern hybrid from the Punch family with a dark cherry and grape aroma. Plants are compact with dense, often deep purple buds; good airflow helps against mould in the tight colas.', 'Moderní hybrid s převahou indiky z rodiny Punch, s vůní tmavých třešní a hroznů. Rostliny jsou kompaktní s hustými, často tmavě fialovými palicemi; dobré proudění vzduchu pomáhá proti plísni v hutných vrcholech.'),
('black-domina', 'Black Domina', 'Sensi Seeds', 'indica', 'photo', 7, 9, 'Black Domina is a Sensi Seeds indica combining Northern Lights, Ortega, Hash Plant and Afghani lines. Plants stay short and bushy with broad dark leaves and heavy, resin-coated buds. It is a classic choice for compact indoor setups.', 'Black Domina je indika od Sensi Seeds, která spojuje linie Northern Lights, Ortega, Hash Plant a Afghani. Rostliny zůstávají nízké a košaté, se širokými tmavými listy a těžkými palicemi obalenými pryskyřicí. Je to klasická volba pro kompaktní indoor pěstování.'),
('black-jack', 'Black Jack', 'Sweet Seeds', 'hybrid', 'photo', 8, 9, 'Black Jack from Sweet Seeds combines Black Domina with Jack Herer. Plants grow tall with a strong central cola and good side branching, so topping or SCROG helps indoors. Buds are dense and resinous, with a spicy, incense-like aroma.', 'Black Jack od Sweet Seeds spojuje Black Domina a Jack Herer. Rostliny rostou vysoko se silnou hlavní palicí a dobrým větvením, proto se uvnitř vyplatí zaštipování nebo SCROG. Palice jsou husté a pryskyřičné s kořenitou, kadidlovou vůní.'),
('blackberry-kush', 'Blackberry Kush', 'Various', 'indica', 'photo', 8, 9, 'Indica-dominant Kush with a compact, bushy structure and broad leaves. Buds are dense and can take on dark purple tones in cooler night temperatures. Keep humidity low in late flower to avoid bud rot.', 'Indikou dominovaný kush s kompaktním, keřovitým vzrůstem a širokými listy. Palice jsou husté a při chladnějších nocích mohou tmavě fialovět. V pozdním květu držte nízkou vlhkost, aby nehrozila plíseň v palicích.'),
('blue-cheese', 'Blue Cheese', 'Big Buddha Seeds', 'indica', 'photo', 8, 9, 'Indica-leaning cross of Blueberry and the UK Cheese clone. Plants stay fairly compact with dense, resinous buds and a strong cheesy-berry aroma, so carbon filtration is advisable indoors. Suits SCROG or SOG setups and finishes in about two months of bloom.', 'Převážně indická kříženka Blueberry a britského klonu Cheese. Rostliny zůstávají spíše kompaktní, tvoří husté pryskyřičné palice a silně voní po sýru a lesním ovoci, takže se při pěstování uvnitř vyplatí uhlíkový filtr. Hodí se pro SCROG i SOG a kvete zhruba dva měsíce.'),
('blue-cheese-auto', 'Blue Cheese Auto', 'Various', 'indica', 'auto', 6, 8, 'Autoflowering cross of Blueberry and UK Cheese genetics with ruderalis. Short, sturdy plants with a pungent cheesy and sweet berry smell, so odour control is worth planning for.', 'Samonakvétací kříženec genetiky Blueberry a UK Cheese s ruderalis. Nízké, statné rostliny s ostrou sýrovou a sladce bobulovou vůní, proto je dobré počítat s filtrací pachu.'),
('blue-cookies', 'Blue Cookies', 'Various', 'hybrid', 'photo', 8, 9, 'Blue Cookies is a hybrid of Girl Scout Cookies and Blueberry, offered by several breeders. Plants are medium height with dense, frosty buds that can turn purple in cooler night temperatures. Moderate feeding and good airflow suit it best.', 'Blue Cookies je hybrid Girl Scout Cookies a Blueberry, který nabízí více šlechtitelů. Rostliny jsou středně vysoké s hustými, ojíněnými palicemi, které při chladnějších nocích mohou fialovět. Nejlépe mu sedí střední hnojení a dobré proudění vzduchu.'),
('blue-dream-auto', 'Blue Dream Auto', 'Various', 'hybrid', 'auto', 7, 9, 'Blue Dream Auto is an autoflowering version of the popular sativa-leaning Blue Dream, offered by several seed banks. It finishes roughly 10 to 11 weeks from seed without a change in light schedule. Plants stay manageable in height but still reward low-stress training.', 'Blue Dream Auto je samonakvétací verze oblíbené, spíše sativní Blue Dream, kterou nabízí více semenáren. Ze semínka dozrává zhruba za 10 až 11 týdnů bez změny světelného režimu. Rostliny zůstávají zvládnutelně vysoké, ale jemné ohýbání (LST) se i tak vyplatí.'),
('blue-mystic', 'Blue Mystic', 'Nirvana Seeds', 'indica', 'photo', 7, 9, 'Mostly indica hybrid from Nirvana Seeds with a Blueberry background. Stays fairly short and uniform, which suits small tents and sea-of-green setups. Considered forgiving for beginners.', 'Převážně indická odrůda od Nirvana Seeds s blueberry původem. Zůstává poměrně nízká a vyrovnaná, takže se hodí do malých stanů a metody SOG. Platí za shovívavou k začátečníkům.'),
('blue-widow', 'Blue Widow', 'Dinafem', 'hybrid', 'photo', 8, 9, 'Cross of Blueberry and White Widow. Plants are vigorous with a balanced structure, producing frosty, medium-dense buds with a fruity berry aroma. Easy to manage indoors or outdoors and finishes in roughly eight to nine weeks.', 'Kříženec Blueberry a White Widow. Rostliny jsou vitální s vyváženou stavbou a tvoří ojíněné, středně husté palice s ovocnou vůní po borůvkách. Snadno se pěstuje uvnitř i venku a dozrává zhruba za osm až devět týdnů.'),
('blue-zushi', 'Blue Zushi', 'Various', 'hybrid', 'photo', 8, 10, 'Recent Zkittlez-line hybrid known for dark blue-purple colouring and a fruity, gassy terpene profile. Plants are medium in stature with dense buds; colour is strongest with a cooler night-time drop late in flower.', 'Novější hybrid z linie Zkittlez, známý tmavě modrofialovým zbarvením a ovocným, „benzínovým“ aroma. Rostliny jsou středně vysoké s hustými palicemi; barva nejvíc vynikne při chladnějších nocích ke konci květu.'),
('blueberry-kush', 'Blueberry Kush', 'Various', 'indica', 'photo', 8, 9, 'Blueberry Kush is an indica-leaning cross of Blueberry and OG Kush. It grows short and stocky with dense buds and a berry-and-earth aroma. Keep humidity in check during late flower because the colas are tight.', 'Blueberry Kush je křížení Blueberry a OG Kush s převahou indiky. Roste nízko a zavalitě, s hustými palicemi a vůní borůvek a zeminy. V pozdním květu hlídej vlhkost, protože vrcholy jsou velmi husté.'),
('bubba-kush-auto', 'Bubba Kush Auto', 'Various', 'indica', 'auto', 6, 8, 'Bubba Kush Auto is an autoflowering take on the classic indica Bubba Kush, sold by several breeders. Plants stay short and bushy and build compact, dense buds that often darken late in flower. Its small size makes it well suited to tents and discreet balcony grows.', 'Bubba Kush Auto je samonakvétací verze klasické indiky Bubba Kush, kterou nabízí více šlechtitelů. Rostliny zůstávají nízké a košaté a tvoří kompaktní, husté palice, které ke konci kvetení často tmavnou. Díky malé velikosti se hodí do growboxů i na diskrétní pěstování na balkoně.'),
('bubble-gum', 'Bubble Gum', 'Serious Seeds', 'hybrid', 'photo', 8, 9, 'Classic hybrid originating in Indiana and stabilised in the Netherlands, named for its sweet, bubblegum-like scent. Medium-sized plants with a fairly even canopy. Phenotypes can vary, so selecting a keeper is worthwhile.', 'Klasický hybrid původem z Indiany, stabilizovaný v Nizozemsku, pojmenovaný podle sladké vůně připomínající žvýkačku. Středně velké rostliny s poměrně vyrovnaným porostem. Fenotypy se mohou lišit, výběr matky se vyplatí.'),
('bubblegum-kush', 'Bubblegum Kush', 'Various', 'indica', 'photo', 8, 9, 'Indica-leaning hybrid combining Bubblegum and Kush lines, valued for a sweet candy-like aroma. Plants stay short and stocky with dense buds, which makes them practical for small tents. Flowering takes around eight to nine weeks.', 'Převážně indický hybrid spojující linie Bubblegum a Kush, ceněný pro sladkou bonbónovou vůni. Rostliny zůstávají nízké a zavalité s hustými palicemi, takže se hodí i do malých growboxů. Kvetení trvá kolem osmi až devíti týdnů.'),
('candyland', 'Candyland', 'Ken Estes', 'sativa', 'photo', 8, 9, 'Candyland is a sativa-leaning hybrid of Granddaddy Purple and Bay Platinum Cookies, bred by Ken Estes. Plants grow tall with good branching and produce sweet, spicy-smelling buds. It handles training well and suits both indoor and outdoor gardens.', 'Candyland je hybrid s převahou sativy z Granddaddy Purple a Bay Platinum Cookies, který vyšlechtil Ken Estes. Rostliny rostou vysoko, dobře se větví a tvoří sladce kořenitě vonící palice. Dobře snáší tvarování a hodí se pro pěstování uvnitř i venku.'),
('cannatonic', 'Cannatonic', 'Resin Seeds', 'hybrid', 'photo', 8, 10, 'Cannatonic from Resin Seeds (MK Ultra crossed with G13 Haze) is one of the best-known CBD-rich chemotypes, with low THC relative to CBD. Plants grow medium to tall with good branching. Cannabinoid ratios can vary between phenotypes, so lab-testing is the only way to know the result.', 'Cannatonic od Resin Seeds (MK Ultra × G13 Haze) patří k nejznámějším chemotypům bohatým na CBD, s nízkým obsahem THC vůči CBD. Rostliny jsou středně vysoké až vysoké a dobře se větví. Poměr kanabinoidů se mezi fenotypy liší, jistotu dá jen laboratorní test.'),
('cat-piss', 'Cat Piss', 'Various', 'sativa', 'photo', 9, 10, 'Sativa-leaning cut from the Super Silver Haze family, named for its sharp, ammonia-like smell. Tall and stretchy in early flower, so plan for training or extra headroom. Strong odour makes carbon filtration essential.', 'Sativní klon z rodiny Super Silver Haze, pojmenovaný podle ostrého zápachu připomínajícího čpavek. V začátku květu se výrazně natahuje, počítejte s tvarováním nebo místem navíc. Kvůli silnému pachu je uhlíkový filtr nutnost.'),
('cbd-critical-mass', 'CBD Critical Mass', 'Dinafem', 'indica', 'photo', 7, 8, 'CBD-rich version of Critical Mass with roughly balanced CBD and THC. Like its parent it is a fast, heavy-yielding indica-leaning plant whose large colas need support and good airflow to avoid bud rot.', 'Verze Critical Mass s vysokým obsahem CBD, přibližně vyrovnaným s THC. Stejně jako rodič je to rychlá, výnosná rostlina s převahou indiky, jejíž velké vrcholy potřebují oporu a dobré proudění vzduchu proti hnilobě.'),
('cereal-milk', 'Cereal Milk', 'Cookies / Powerzzzup Genetics', 'hybrid', 'photo', 8, 9, 'Balanced hybrid from the Cookies collaboration with Powerzzzup Genetics, bred from Y Life and Snowman. Medium-height plants with frosty, light-green buds and a sweet, creamy aroma. Flowering takes about eight to nine weeks.', 'Vyvážený hybrid ze spolupráce Cookies a Powerzzzup Genetics, vyšlechtěný z Y Life a Snowman. Středně vysoké rostliny s ojíněnými světle zelenými palicemi a sladkou krémovou vůní. Kvetení trvá zhruba osm až devět týdnů.'),
('champagne', 'Champagne', 'Various', 'hybrid', 'photo', 8, 10, 'Name used for several hybrids with a sweet, fruity and slightly floral aroma. Growth is typically medium-tall with moderate stretch; check the breeder description of the specific cut, as genetics vary between sources.', 'Název používaný pro několik hybridů se sladkým, ovocným a lehce květinovým aroma. Růst bývá středně vysoký se střední mírou natahování; u konkrétní genetiky je dobré ověřit popis šlechtitele, protože se mezi zdroji liší.'),
('charlottes-web', 'Charlottes Web', 'Stanley Brothers', 'sativa', 'photo', 8, 10, 'Charlotte''s Web is a high-CBD, very low-THC line developed by the Stanley Brothers in Colorado. It grows like a tall, airy sativa-type plant and is mostly cultivated as hemp. Buds are lighter and less dense than typical drug-type strains.', 'Charlotte''s Web je linie s vysokým obsahem CBD a velmi nízkým THC, kterou vyvinuli bratři Stanleyové v Coloradu. Roste jako vysoká, vzdušná rostlina sativního typu a pěstuje se hlavně jako konopí technické. Palice jsou lehčí a méně husté než u běžných odrůd.'),
('cheese-auto', 'Cheese Auto', 'Various', 'hybrid', 'auto', 6, 8, 'Cheese Auto is an autoflowering version of the UK Cheese family, available from several seed banks. It grows compact, indica-leaning plants with a pungent, savoury aroma that calls for good odour control. Typical seed-to-harvest time is about 9 to 10 weeks.', 'Cheese Auto je samonakvétací verze z rodiny UK Cheese, kterou nabízí více semenáren. Roste kompaktně, spíše indikově, a má výraznou pikantní vůni, se kterou je dobré počítat (uhlíkový filtr). Od semínka ke sklizni obvykle uplyne 9 až 10 týdnů.'),
('chem-dog-auto', 'Chem Dog Auto', 'Various', 'hybrid', 'auto', 7, 9, 'Autoflowering take on Chemdog, sold by several seedbanks. Produces pungent, fuel-scented buds on a medium-sized frame. Low-stress training helps open the canopy without stalling growth.', 'Samonakvétací verze Chemdogu, kterou prodává více semenáren. Na středně velké rostlině tvoří výrazně páchnoucí palice s tónem nafty. Jemné tvarování (LST) pomůže otevřít porost bez zbrzdění růstu.'),
('cherry-gelato', 'Cherry Gelato', 'Various', 'hybrid', 'photo', 8, 10, 'Gelato-family hybrid with a sweet cherry and berry aroma. Plants are medium-sized with dense, colourful buds and a thick trichome layer; training helps even out the canopy.', 'Hybrid z rodiny Gelato se sladkou třešňovou a bobulovou vůní. Rostliny jsou středně velké s hustými, barevnými palicemi a silnou vrstvou trichomů; tvarování pomáhá vyrovnat porost.'),
('cherry-pie', 'Cherry Pie', 'Various', 'hybrid', 'photo', 8, 9, 'Cherry Pie is an indica-leaning hybrid of Granddaddy Purple and Durban Poison. It grows to medium height with compact, resinous buds that may show purple hues. A sweet, sour-cherry aroma develops late in flower.', 'Cherry Pie je hybrid s převahou indiky z Granddaddy Purple a Durban Poison. Dorůstá střední výšky a tvoří kompaktní, pryskyřičnaté palice, které mohou mít fialový nádech. Sladce nakyslá třešňová vůně se rozvine v pozdním květu.'),
('chocolate-thai', 'Chocolate Thai', 'Landrace', 'sativa', 'photo', 11, 14, 'Chocolate Thai is a Thai landrace sativa that was widely known in the 1960s and 70s. Plants grow tall and lanky with long internodes and airy, slow-maturing buds. It needs a long season or a large indoor space and plenty of patience.', 'Chocolate Thai je thajská krajová sativa, která byla rozšířená v 60. a 70. letech. Rostliny jsou vysoké a vytáhlé s dlouhými rozestupy kolen a vzdušnými, pomalu dozrávajícími palicemi. Vyžaduje dlouhou sezónu nebo hodně prostoru uvnitř a dávku trpělivosti.'),
('chocolope', 'Chocolope', 'DNA Genetics', 'sativa', 'photo', 8, 10, 'Sativa from DNA Genetics with a chocolate-and-coffee aroma. Plants stretch noticeably and produce long, foxtail-prone colas. Training and good airflow keep the canopy manageable.', 'Sativa od DNA Genetics s vůní čokolády a kávy. Rostliny se znatelně natahují a tvoří dlouhé palice se sklonem k foxtailingu. Tvarování a dobré proudění vzduchu udrží porost zvládnutelný.'),
('cinderella-99', 'Cinderella 99', 'Brothers Grimm Seeds', 'sativa', 'photo', 7, 9, 'Fast-finishing sativa selected by Brothers Grimm, often shortened to C99. Plants stay relatively compact for a sativa, with fruity, resinous colas and good yields for their size. Usually ready after seven to nine weeks of flowering.', 'Rychle dozrávající sativa vyšlechtěná Brothers Grimm, často zkracovaná jako C99. Na sativu zůstávají rostliny poměrně kompaktní, tvoří ovocně vonící pryskyřičné palice a na svou velikost slušně rodí. Obvykle je hotová po sedmi až devíti týdnech kvetení.'),
('colombian-gold', 'Colombian Gold', 'Landrace', 'sativa', 'photo', 10, 13, 'Classic landrace sativa from the Santa Marta mountains of Colombia and an ancestor of many Skunk lines. Plants grow tall and airy with long flowering, so it is better suited to outdoor or large indoor spaces.', 'Klasická krajová sativa z pohoří Santa Marta v Kolumbii a předek mnoha linií Skunk. Rostliny rostou vysoké a vzdušné s dlouhým kvetením, proto se hodí spíš ven nebo do velkých prostor.'),
('cookies-and-cream', 'Cookies and Cream', 'Exotic Genetix', 'hybrid', 'photo', 8, 10, 'Cookies and Cream is an Exotic Genetix hybrid from Starfighter and a Girl Scout Cookies selection. It is a vigorous, medium-tall plant with dense, frosty buds. Training helps spread the canopy and even out cola size.', 'Cookies and Cream je hybrid od Exotic Genetix ze Starfighter a selekce Girl Scout Cookies. Je to vitální, středně vysoká rostlina s hustými, ojíněnými palicemi. Tvarování pomáhá rozprostřít korunu a vyrovnat velikost vrcholů.'),
('critical-auto', 'Critical+ Auto', 'Dinafem', 'indica', 'auto', 6, 7, 'Autoflowering version of Dinafem''s Critical+, bred for short cycles and heavy yields. Plants stay compact with a dominant central cola and dense buds, making them suitable for small spaces and outdoor summer runs. The bloom phase lasts roughly six to seven weeks.', 'Samonakvétací verze Critical+ od Dinafemu, vyšlechtěná pro krátký cyklus a vysoké výnosy. Rostliny zůstávají kompaktní s výraznou hlavní palicí a hustými květy, takže se hodí do malých prostor i na letní venkovní pěstování. Fáze květu trvá zhruba šest až sedm týdnů.'),
('critical-kush', 'Critical Kush', 'Barney''s Farm', 'indica', 'photo', 7, 8, 'Indica from Barney''s Farm combining Critical Mass and OG Kush lines. Fast-finishing and compact with heavy, dense colas. Heavy buds may need support, and low humidity matters late in flower.', 'Indika od Barney''s Farm spojující linie Critical Mass a OG Kush. Rychle dozrává, je kompaktní a tvoří těžké, husté palice. Těžké palice mohou potřebovat podepřít a v pozdním květu záleží na nízké vlhkosti.'),
('death-star', 'Death Star', 'Various', 'indica', 'photo', 8, 10, 'Indica-leaning hybrid of Sensi Star and Sour Diesel from Ohio. Medium plants with a strong diesel and skunk smell and dense, resinous buds; carbon filtration is recommended indoors.', 'Hybrid s převahou indiky ze Sensi Star a Sour Diesel, pocházející z Ohia. Středně velké rostliny se silnou naftovou a skunkovou vůní a hustými pryskyřičnými palicemi; uvnitř se doporučuje uhlíkový filtr.'),
('diesel', 'Diesel', 'Various', 'hybrid', 'photo', 9, 11, 'Diesel is an East Coast classic from the Chemdawg family, known for its sharp fuel aroma. Plants stretch noticeably in flower and produce long, spear-shaped colas. It is the ancestor of Sour Diesel and many related cuts.', 'Diesel je klasika z východního pobřeží USA z rodiny Chemdawg, známá ostrou vůní připomínající palivo. Rostliny se v květu výrazně natahují a tvoří dlouhé, kopinaté vrcholy. Je předkem Sour Diesel a mnoha příbuzných klonů.'),
('dinamed-cbd', 'Dinamed CBD', 'Dinafem', 'hybrid', 'photo', 8, 9, 'Dinamed CBD is a CBD-rich hybrid from Dinafem with very low THC. Plants grow vigorously with good branching and produce resinous, medium-density buds. As with other CBD lines, the final cannabinoid ratio should be confirmed by testing.', 'Dinamed CBD je hybrid od Dinafem bohatý na CBD s velmi nízkým obsahem THC. Rostliny rostou bujně, dobře se větví a tvoří pryskyřičné palice střední hustoty. Stejně jako u jiných CBD odrůd je konečný poměr kanabinoidů dobré ověřit testem.'),
('dosidos-auto', 'Dosidos Auto', 'Various', 'indica', 'auto', 7, 9, 'Autoflowering version of Do-Si-Dos offered by several seedbanks. Compact plants with dense, frosty buds that can show purple hues. Suits small spaces and short growing seasons.', 'Samonakvétací verze Do-Si-Dos od více semenáren. Kompaktní rostliny s hustými, ojíněnými palicemi, které mohou fialovět. Hodí se do malých prostor i na krátkou sezónu.'),
('durban-poison-auto', 'Durban Poison Auto', 'Various', 'sativa', 'auto', 7, 9, 'Autoflowering take on the South African Durban Poison landrace. Plants keep a slender sativa shape with long, airy-to-medium colas and a sweet anise-like aroma. The bloom phase usually lasts seven to nine weeks.', 'Samonakvétací verze jihoafrické krajové odrůdy Durban Poison. Rostliny si drží štíhlý sativový tvar s dlouhými, spíše vzdušnými palicemi a sladkou vůní připomínající anýz. Fáze květu obvykle trvá sedm až devět týdnů.'),
('dutch-treat', 'Dutch Treat', 'Various', 'indica', 'photo', 8, 9, 'Long-established Dutch-style hybrid with a sweet pine and eucalyptus aroma. Plants are compact to medium with good resin production and are regarded as forgiving for less experienced growers.', 'Dlouho známý hybrid holandského typu se sladkou vůní borovice a eukalyptu. Rostliny jsou kompaktní až středně velké s dobrou tvorbou pryskyřice a považují se za shovívavé k méně zkušeným pěstitelům.'),
('easy-bud', 'Easy Bud', 'Royal Queen Seeds', 'hybrid', 'auto', 5, 6, 'Easy Bud is a Royal Queen Seeds autoflower designed as a forgiving first grow. Plants stay small and finish quickly from seed, making it suitable for small spaces and short outdoor seasons. Avoid heavy feeding and transplant stress.', 'Easy Bud je samonakvétací odrůda od Royal Queen Seeds, navržená jako tolerantní volba pro první pěstování. Rostliny zůstávají malé a ze semínka dozrávají rychle, takže se hodí do malých prostor i na krátkou venkovní sezónu. Vyhni se silnému hnojení a stresu z přesazování.'),
('ed-rosenthal-super-bud', 'Ed Rosenthal Super Bud', 'Sensi Seeds', 'indica', 'photo', 7, 9, 'Ed Rosenthal Super Bud is an indica-dominant hybrid from Sensi Seeds, named after the well-known cultivation author. It forms a strong main cola surrounded by productive side branches. Plants are fairly easy to grow and stay at a moderate height indoors.', 'Ed Rosenthal Super Bud je indikově dominantní hybrid od Sensi Seeds, pojmenovaný po známém autorovi pěstitelských příruček. Tvoří silnou hlavní palici obklopenou výnosnými bočními větvemi. Pěstuje se poměrně snadno a uvnitř zůstává středně vysoký.'),
('exodus-cheese', 'Exodus Cheese', 'Exodus Collective (clone-only)', 'hybrid', 'photo', 8, 9, 'Famous UK clone-only Skunk #1 phenotype, often simply called UK Cheese. Medium height with a sharp, cheesy aroma that needs serious odour control. Seed versions from various breeders try to recreate the cut.', 'Slavný britský klon fenotypu Skunk #1, často nazývaný prostě UK Cheese. Středně vysoká rostlina s ostrou sýrovou vůní, která vyžaduje důkladné odvětrání a filtraci. Různé semenárny nabízejí semínkové verze napodobující tento klon.'),
('fastberry', 'Fastberry', 'Various', 'hybrid', 'auto', 6, 8, 'Fast autoflowering hybrid with a sweet berry aroma. Compact plants with short internodes fit small tents and balconies, and they need little training. The bloom phase typically lasts six to eight weeks.', 'Rychlý samonakvétací hybrid se sladkou vůní lesního ovoce. Kompaktní rostliny s krátkými internodii se vejdou do malých growboxů i na balkon a nepotřebují mnoho tréninku. Fáze květu obvykle trvá šest až osm týdnů.'),
('fire-og', 'Fire OG', 'Various', 'hybrid', 'photo', 9, 10, 'OG Kush descendant, commonly listed as OG Kush x SFV OG. Plants stretch noticeably in early flower and produce very resinous, lemon-fuel scented buds with modest yields.', 'Potomek OG Kush, obvykle uváděný jako OG Kush x SFV OG. Rostliny se na začátku květu výrazně natahují a tvoří velmi pryskyřičné palice s citronovo-palivovou vůní při spíše skromném výnosu.'),
('forbidden-fruit', 'Forbidden Fruit', 'Various', 'indica', 'photo', 8, 9, 'Forbidden Fruit is an indica-leaning hybrid known for its tropical, fruity aroma. Plants are medium-sized and bushy, often showing purple and dark tones in cooler conditions. Dense buds benefit from good airflow and moderate humidity.', 'Forbidden Fruit je hybrid s převahou indiky, známý tropickou ovocnou vůní. Rostliny jsou středně velké a košaté a v chladnějších podmínkách často fialoví a tmavnou. Husté palice ocení dobré proudění vzduchu a mírnou vlhkost.'),
('gary-payton', 'Gary Payton', 'Cookies / Powerzzzup Genetics', 'hybrid', 'photo', 8, 10, 'Balanced hybrid from Cookies and Powerzzzup Genetics, bred from The Y and Snowman. Medium-sized plants produce dense, frosty buds with a gassy, peppery aroma. Flowering takes roughly eight to ten weeks.', 'Vyvážený hybrid od Cookies a Powerzzzup Genetics, vyšlechtěný z The Y a Snowman. Středně velké rostliny tvoří husté, ojíněné palice s benzínovo-pepřovou vůní. Kvetení trvá zhruba osm až deset týdnů.'),
('gelato-auto', 'Gelato Auto', 'Various', 'hybrid', 'auto', 7, 9, 'Autoflowering version of Gelato, combining the dessert-like sweet aroma of the original with ruderalis genetics. Plants stay compact and finish quickly from seed, though trichome-heavy buds still benefit from a full flowering run.', 'Samonakvétací verze Gelata, která spojuje sladkou „dezertní“ vůni originálu s genetikou ruderalis. Rostliny zůstávají kompaktní a od semínka dozrají rychle, palice bohaté na trichomy ale potřebují nechat dokvést celou dobu.'),
('ghost-og', 'Ghost OG', 'Various', 'hybrid', 'photo', 9, 10, 'Ghost OG is a selected phenotype of OG Kush circulated as a clone-only cut. Like other OGs it stretches in flower and needs support for its heavy, resinous colas. It prefers a stable environment and careful feeding.', 'Ghost OG je vybraný fenotyp OG Kush šířený jako klon. Stejně jako ostatní OG se v květu natahuje a jeho těžké, pryskyřičnaté vrcholy potřebují oporu. Vyhovuje mu stabilní prostředí a opatrné hnojení.'),
('girl-scout-cookies-auto', 'Girl Scout Cookies Auto', 'Various', 'hybrid', 'auto', 7, 8, 'Girl Scout Cookies Auto is an autoflowering version of GSC, sold by several seed banks. Plants are compact with dense, resinous buds that can take on purple hues in cooler nights. Total time from seed is usually around 10 weeks.', 'Girl Scout Cookies Auto je samonakvétací verze GSC, kterou nabízí více semenáren. Rostliny jsou kompaktní s hustými, pryskyřičnými palicemi, které se při chladnějších nocích mohou zbarvit do fialova. Celková doba od semínka bývá kolem 10 týdnů.'),
('gmo', 'GMO', 'Various', 'indica', 'photo', 9, 11, 'GMO, also known as Garlic Cookies, is a cross of Chemdog and Girl Scout Cookies with a pungent garlic and diesel aroma. Plants stretch noticeably in early flower and need a long bloom period. Dense, frosty buds benefit from good airflow to avoid mould.', 'GMO, známá také jako Garlic Cookies, je kříženec Chemdog a Girl Scout Cookies s pronikavou česnekovo-naftovou vůní. Na začátku kvetení se výrazně natahuje a potřebuje dlouhou dobu kvetení. Husté, ojíněné palice vyžadují dobré proudění vzduchu kvůli plísni.'),
('gorilla-cookies', 'Gorilla Cookies', 'Various', 'hybrid', 'photo', 8, 9, 'Hybrid built on Gorilla Glue and Cookies genetics, offered by several breeders. Produces very resinous buds on a medium-sized, branching frame. Topping and defoliation help light reach the lower sites.', 'Hybrid postavený na genetice Gorilla Glue a Cookies, nabízený více šlechtiteli. Na středně velké, větvené rostlině tvoří velmi pryskyřičné palice. Zaštípnutí a odlistění pomohou dostat světlo i ke spodním květům.'),
('grape-ape', 'Grape Ape', 'Apothecary Genetics', 'indica', 'photo', 7, 9, 'Indica-dominant strain with Mendocino Purps, Skunk and Afghani in its background. Short, bushy plants form dense buds that often turn purple when night temperatures drop, with a sweet grape aroma. Flowering takes about seven to nine weeks.', 'Převážně indická odrůda s Mendocino Purps, Skunkem a Afghánem v rodokmenu. Nízké, košaté rostliny tvoří husté palice, které při chladnějších nocích často fialoví, a voní sladce po hroznech. Kvetení trvá asi sedm až devět týdnů.'),
('grape-god', 'Grape God', 'Various', 'indica', 'photo', 8, 9, 'Indica-dominant hybrid from British Columbia with God Bud in its background and a strong grape aroma. Plants are stocky with dense buds that may turn purple late in flower.', 'Hybrid s převahou indiky z Britské Kolumbie s God Bud v pozadí a výraznou hroznovou vůní. Rostliny jsou zavalité s hustými palicemi, které mohou ke konci květu fialovět.'),
('grape-pie', 'Grape Pie', 'Various', 'hybrid', 'photo', 8, 9, 'Grape Pie is an indica-leaning hybrid of Cherry Pie and Grape Stomper. It grows compact with dense, frosty buds that often turn purple. Expect a sweet grape aroma by the end of flowering.', 'Grape Pie je hybrid s převahou indiky z Cherry Pie a Grape Stomper. Roste kompaktně, s hustými ojíněnými palicemi, které často fialoví. Ke konci květu počítej se sladkou hroznovou vůní.'),
('green-crack-auto', 'Green Crack Auto', 'Various', 'sativa', 'auto', 6, 8, 'Green Crack Auto is an autoflowering version of the sativa-leaning Green Crack, available from several breeders. Plants grow a bit taller than typical autos and produce elongated, citrus-scented buds. It finishes roughly 9 to 11 weeks from seed.', 'Green Crack Auto je samonakvétací verze spíše sativní Green Crack od více šlechtitelů. Rostliny bývají o něco vyšší než běžné automatky a tvoří protáhlé palice s citrusovou vůní. Dozrává zhruba za 9 až 11 týdnů od semínka.'),
('green-gelato', 'Green Gelato', 'Various', 'hybrid', 'photo', 8, 9, 'Gelato-line hybrid that, as the name suggests, tends to stay green rather than purple. Moderate height and dense, sticky buds. A steady environment and moderate feeding suit it best.', 'Hybrid z linie Gelato, který jak název napovídá spíše zůstává zelený než fialový. Středně vysoký, s hustými lepkavými palicemi. Nejlépe mu sedí stabilní prostředí a umírněné hnojení.'),
('gushers', 'Gushers', 'Cookies', 'indica', 'photo', 8, 9, 'Indica-leaning cross of Gelato #41 and Triangle Kush from the Cookies family. Plants stay medium height with dense, colourful buds and a sweet tropical-fruit aroma. Usually ready after eight to nine weeks of bloom.', 'Převážně indický kříženec Gelato #41 a Triangle Kush z rodiny Cookies. Rostliny dorůstají střední výšky a tvoří husté, barevné palice se sladkou vůní tropického ovoce. Obvykle je hotová po osmi až devíti týdnech květu.'),
('harle-tsu', 'Harle-Tsu', 'Various', 'hybrid', 'photo', 9, 10, 'High-CBD hybrid of Harlequin and Sour Tsunami with very low THC. Plants grow medium-tall with moderate yields; because CBD levels vary between phenotypes, clones or tested seed lines are preferred.', 'Hybrid s vysokým CBD z Harlequin a Sour Tsunami s velmi nízkým THC. Rostliny rostou středně vysoké se středním výnosem; protože obsah CBD se mezi fenotypy liší, dává se přednost řízkům nebo testovaným liniím.'),
('harlequin', 'Harlequin', 'Various', 'sativa', 'photo', 9, 11, 'Harlequin is a sativa-dominant, CBD-rich strain with landrace roots including Colombian Gold and Thai. Plants are tall and lanky with an open structure. It is grown mainly for its high CBD to THC ratio.', 'Harlequin je odrůda s převahou sativy a vysokým obsahem CBD, s kořeny v landrasech včetně Colombian Gold a Thai. Rostliny jsou vysoké a vytáhlé, s otevřenou stavbou. Pěstuje se hlavně kvůli vysokému poměru CBD k THC.'),
('hash-plant', 'Hash Plant', 'Sensi Seeds', 'indica', 'photo', 6, 8, 'Hash Plant is an Afghani-derived indica line distributed by Sensi Seeds. It grows short and stocky with broad leaves and finishes quickly with heavy resin production. It is well suited to small spaces and sea-of-green setups.', 'Hash Plant je indická linie odvozená z afghánské genetiky, kterou distribuuje Sensi Seeds. Roste nízko a zavalitě se širokými listy, rychle dozrává a tvoří hodně pryskyřice. Hodí se do malých prostor a pro metodu sea of green.'),
('hashberry', 'Hashberry', 'Mr. Nice Seeds', 'indica', 'photo', 7, 9, 'Indica-dominant hybrid from Mr. Nice Seeds bred with hash making in mind. Compact and robust with heavy resin production. Handles both indoor and sheltered outdoor grows.', 'Převážně indický hybrid od Mr. Nice Seeds šlechtěný s ohledem na výrobu hašiše. Kompaktní a odolná rostlina s velkou produkcí pryskyřice. Zvládne pěstování uvnitř i na chráněném místě venku.'),
('hawaiian-snow', 'Hawaiian Snow', 'Green House Seeds', 'sativa', 'photo', 11, 14, 'Haze-based sativa from Green House Seeds with Hawaiian and Neville''s Haze influence. Tall, vigorous plants need plenty of vertical space and a long bloom, producing long, frosty colas. Flowering commonly runs eleven to fourteen weeks.', 'Sativa z linie Haze od Green House Seeds s havajským vlivem a Neville''s Haze. Vysoké, vitální rostliny potřebují hodně prostoru na výšku a dlouhé kvetení, za které vytvoří dlouhé ojíněné palice. Kvetení běžně trvá jedenáct až čtrnáct týdnů.'),
('haze', 'Haze', 'Landrace', 'sativa', 'photo', 12, 16, 'Classic sativa developed in California in the late 1960s and 1970s from tropical landraces. Plants are tall and lanky with very long flowering and airy, incense-scented buds, making it a challenge indoors.', 'Klasická sativa vyšlechtěná v Kalifornii koncem 60. a v 70. letech z tropických krajových odrůd. Rostliny jsou vysoké a vytáhlé s velmi dlouhým kvetením a vzdušnými palicemi vonícími po kadidle, takže uvnitř jsou náročné.'),
('headband', 'Headband', 'Various', 'hybrid', 'photo', 9, 10, 'Headband is a hybrid of OG Kush and Sour Diesel with a creamy, lemon-fuel aroma. Plants stretch in flower and benefit from topping or a scrog net. Colas are long and resinous.', 'Headband je hybrid OG Kush a Sour Diesel s krémovou vůní citronu a paliva. Rostliny se v květu natahují a prospívá jim zaštipování nebo síť (SCROG). Vrcholy jsou dlouhé a pryskyřičnaté.'),
('ice-cream-cake', 'Ice Cream Cake', 'Seed Junky Genetics', 'indica', 'photo', 8, 10, 'Ice Cream Cake from Seed Junky Genetics crosses Wedding Cake with Gelato #33. Plants are indica-leaning, medium-sized and develop very dense, heavily frosted buds. Good airflow and moderate humidity late in flower help keep the dense colas healthy.', 'Ice Cream Cake od Seed Junky Genetics je kříženec Wedding Cake a Gelato #33. Rostliny jsou spíše indikové, středně velké a tvoří velmi husté, silně ojíněné palice. Dobré proudění vzduchu a mírná vlhkost v pozdním kvetení pomáhají udržet husté palice zdravé.'),
('jack-flash', 'Jack Flash', 'Sensi Seeds', 'sativa', 'photo', 8, 9, 'Sativa-dominant hybrid from Sensi Seeds in the Jack Herer family. Vigorous, fairly tall plants with long colas. Training helps keep the canopy even indoors.', 'Sativou dominovaný hybrid od Sensi Seeds z rodiny Jack Herer. Vitální, poměrně vysoké rostliny s dlouhými palicemi. Uvnitř pomáhá tvarování udržet vyrovnaný porost.'),
('jack-herer-auto', 'Jack Herer Auto', 'Various', 'sativa', 'auto', 7, 9, 'Autoflowering version of the classic Jack Herer, combining its Haze-influenced profile with ruderalis genetics. Plants stay manageable in size with a sativa-leaning structure and spicy-pine aroma. The bloom phase lasts about seven to nine weeks.', 'Samonakvétací verze klasického Jack Herer, která spojuje jeho haze profil s genetikou ruderalis. Rostliny zůstávají zvládnutelné velikosti se sativovou stavbou a kořenitě borovicovou vůní. Fáze květu trvá zhruba sedm až devět týdnů.'),
('jack-the-ripper', 'Jack the Ripper', 'TGA Subcool Seeds', 'sativa', 'photo', 8, 10, 'Sativa-leaning hybrid of Jack''s Cleaner and Space Queen with a sharp lemon aroma. Plants stretch and form spear-shaped, extremely resinous colas; topping or a scrog helps manage height.', 'Hybrid s převahou sativy z Jack''s Cleaner a Space Queen s ostrou citronovou vůní. Rostliny se natahují a tvoří kopinaté, velmi pryskyřičné vrcholy; zaštípnutí nebo síť (scrog) pomáhá zvládnout výšku.'),
('jealousy', 'Jealousy', 'Seed Junky Genetics', 'hybrid', 'photo', 8, 9, 'Jealousy is a Seed Junky Genetics hybrid of Sherbert and Gelato #41. It grows to medium height with strong lateral branching and dense, frosty buds. It responds well to training and a steady feeding schedule.', 'Jealousy je hybrid od Seed Junky Genetics ze Sherbert a Gelato #41. Dorůstá střední výšky, silně se větví do stran a tvoří husté, ojíněné palice. Dobře reaguje na tvarování a pravidelné hnojení.'),
('jilly-bean', 'Jilly Bean', 'TGA Subcool Seeds', 'hybrid', 'photo', 8, 9, 'Jilly Bean is a TGA Subcool hybrid of Orange Velvet and Space Queen with a strong citrus aroma. Plants are medium-sized with good branching and respond well to training. Some phenotypes show colourful foliage late in flower.', 'Jilly Bean je hybrid od TGA Subcool z Orange Velvet a Space Queen s výraznou citrusovou vůní. Rostliny jsou středně velké, dobře se větví a dobře reagují na tvarování. Některé fenotypy mají ke konci kvetení barevné listy.'),
('kalashnikova', 'Kalashnikova', 'Green House Seeds', 'indica', 'photo', 8, 9, 'Indica-dominant hybrid from Green House Seeds with an AK-47 background. Medium height, sturdy branching and compact, resinous buds. Generally easy to manage indoors.', 'Převážně indický hybrid od Green House Seeds s původem v AK-47. Středně vysoký, s pevnými větvemi a kompaktními pryskyřičnými palicemi. Uvnitř se obecně snadno zvládá.'),
('kali-mist', 'Kali Mist', 'Serious Seeds', 'sativa', 'photo', 10, 11, 'Sativa-dominant classic from Serious Seeds. Tall, airy plants with long, foxtail-prone colas resist mould well and suit growers with enough height and patience. Flowering takes around ten to eleven weeks.', 'Převážně sativová klasika od Serious Seeds. Vysoké, vzdušné rostliny s dlouhými palicemi odolávají plísni a hodí se pro pěstitele s dostatkem výšky a trpělivosti. Kvetení trvá kolem deseti až jedenácti týdnů.'),
('kosher-kush', 'Kosher Kush', 'DNA Genetics', 'indica', 'photo', 8, 9, 'Indica OG-type strain with an earthy, fuel and pine aroma. Plants are relatively compact with dense, resinous buds and modest yields; they respond well to training.', 'Indika typu OG se zemitou, palivovou a borovicovou vůní. Rostliny jsou poměrně kompaktní s hustými pryskyřičnými palicemi a spíše skromným výnosem; dobře reagují na tvarování.'),
('kush-mints', 'Kush Mints', 'Seed Junky Genetics', 'hybrid', 'photo', 8, 10, 'Kush Mints is a Seed Junky Genetics hybrid of Bubba Kush and Animal Mints. Plants are medium-sized and fairly compact with very resinous, dense buds. A minty, earthy aroma develops in late flower.', 'Kush Mints je hybrid od Seed Junky Genetics z Bubba Kush a Animal Mints. Rostliny jsou středně velké a spíše kompaktní, s velmi pryskyřičnatými, hustými palicemi. V pozdním květu se rozvine mátově zemitá vůně.'),
('la-confidential', 'LA Confidential', 'DNA Genetics', 'indica', 'photo', 7, 9, 'LA Confidential from DNA Genetics is an indica built from OG LA Affie and Afghani. Plants stay compact with tight internodes and produce dense, frosty buds that can turn purple in cool conditions. It is a straightforward grow suited to small indoor spaces.', 'LA Confidential od DNA Genetics je indika vzniklá z OG LA Affie a Afghani. Rostliny zůstávají kompaktní s krátkými rozestupy a tvoří husté, ojíněné palice, které mohou v chladu zfialovět. Pěstuje se snadno a hodí se do menších vnitřních prostor.'),
('lambs-bread', 'Lambs Bread', 'Landrace', 'sativa', 'photo', 9, 11, 'Jamaican landrace sativa, also written Lamb''s Bread. Tall, open plants with narrow leaves and airy buds. Best suited to warm climates or growers with plenty of headroom.', 'Jamajská krajová sativa, psaná také Lamb''s Bread. Vysoké, řídké rostliny s úzkými listy a vzdušnými palicemi. Nejlépe se hodí do teplého klimatu nebo tam, kde je dost místa na výšku.'),
('larry-og', 'Larry OG', 'Various', 'hybrid', 'photo', 8, 9, 'California OG Kush cut also known as Lemon Larry OG. Plants show typical OG structure with moderate stretch and dense, lemon-fuel scented buds that need support late in bloom. Flowering takes about eight to nine weeks.', 'Kalifornský klon OG Kush známý také jako Lemon Larry OG. Rostliny mají typickou OG stavbu se středním natahováním a husté palice vonící po citronu a naftě, které na konci květu potřebují oporu. Kvetení trvá asi osm až devět týdnů.'),
('lavender', 'Lavender', 'Soma Seeds', 'indica', 'photo', 8, 10, 'Indica-dominant hybrid with Super Skunk, Big Skunk Korean and Afghani Hawaiian in its background. Known for purple-tinged leaves and buds and a floral, spicy aroma; plants stay medium-sized.', 'Hybrid s převahou indiky, v jehož pozadí jsou Super Skunk, Big Skunk Korean a Afghani Hawaiian. Je známý fialově laděnými listy i palicemi a květinově kořeněnou vůní; rostliny zůstávají středně velké.'),
('lemon-cake', 'Lemon Cake', 'Various', 'sativa', 'photo', 8, 10, 'Lemon Cake is a sativa-leaning strain with a bright lemon and sweet aroma. Plants grow tall with good branching and produce elongated, resinous buds. Give it vertical room or train it early.', 'Lemon Cake je odrůda s převahou sativy a výraznou citronově sladkou vůní. Rostliny rostou vysoko, dobře se větví a tvoří protáhlé, pryskyřičnaté palice. Dopřej jí prostor na výšku nebo ji tvaruj včas.'),
('lemon-cherry-gelato', 'Lemon Cherry Gelato', 'Backpackboyz', 'hybrid', 'photo', 8, 10, 'Lemon Cherry Gelato is a modern dessert hybrid popularised by the Bay Area brand Backpackboyz. Plants are medium-sized and produce dense, colourful, resin-heavy buds with a sweet citrus aroma. Its exact lineage is reported differently by different sources.', 'Lemon Cherry Gelato je moderní dezertní hybrid, který proslavila značka Backpackboyz ze San Francisca. Rostliny jsou středně velké a tvoří husté, barevné a pryskyřičné palice se sladce citrusovou vůní. Přesný původ uvádějí různé zdroje odlišně.'),
('lemon-haze', 'Lemon Haze', 'Various', 'sativa', 'photo', 9, 10, 'Sativa-dominant Haze with a strong lemon-peel aroma, offered by many seedbanks. Tall and stretchy with long, airy colas. Benefits from training and good airflow.', 'Sativou dominovaný haze se silnou vůní citronové kůry, který nabízí řada semenáren. Vysoký a natahující se, s dlouhými vzdušnými palicemi. Prospívá mu tvarování a dobré proudění vzduchu.'),
('lemon-og', 'Lemon OG', 'Various', 'hybrid', 'photo', 8, 9, 'OG-family hybrid valued for a bright lemon aroma over earthy fuel notes. Plants stretch moderately and form dense, resinous buds; good airflow helps prevent bud rot. Flowering takes roughly eight to nine weeks.', 'Hybrid z rodiny OG ceněný pro výraznou citronovou vůni nad zemitými naftovými tóny. Rostliny se středně natahují a tvoří husté pryskyřičné palice; dobré proudění vzduchu pomáhá předejít hnilobě. Kvetení trvá zhruba osm až devět týdnů.'),
('lemon-skunk', 'Lemon Skunk', 'DNA Genetics', 'sativa', 'photo', 8, 9, 'Sativa-leaning selection from Skunk lines with a pronounced lemon aroma. Plants are vigorous and medium-tall with good yields of fairly dense buds; expect some stretch in early flower.', 'Sativou laděná selekce z linií Skunk s výraznou citronovou vůní. Rostliny jsou vitální a středně vysoké s dobrým výnosem poměrně hustých palic; na začátku květu počítejte s natažením.'),
('lemon-tree', 'Lemon Tree', 'Various', 'hybrid', 'photo', 8, 9, 'Lemon Tree is a hybrid of Lemon Skunk and Sour Diesel with a strong citrus-fuel aroma. Plants are vigorous and medium-tall with dense, resinous buds. It handles topping and low-stress training well.', 'Lemon Tree je hybrid Lemon Skunk a Sour Diesel se silnou vůní citrusů a paliva. Rostliny jsou vitální a středně vysoké, s hustými pryskyřičnatými palicemi. Dobře snáší zaštipování a jemné tvarování (LST).'),
('london-pound-cake', 'London Pound Cake', 'Cookies', 'indica', 'photo', 8, 10, 'London Pound Cake is an indica-leaning dessert hybrid released by Cookies, descended from Sunset Sherbet. Plants are medium height with dense, dark buds that can show purple colouring. Keep humidity in check late in flower because of the tight bud structure.', 'London Pound Cake je spíše indikový dezertní hybrid od Cookies, který pochází ze Sunset Sherbet. Rostliny jsou středně vysoké s hustými, tmavými palicemi, které mohou mít fialové zbarvení. Kvůli husté stavbě palic hlídejte vlhkost v pozdní fázi kvetení.'),
('mac-miracle-alien-cookies', 'MAC (Miracle Alien Cookies)', 'Capulator', 'hybrid', 'photo', 8, 9, 'MAC (Miracle Alien Cookies) from Capulator, an Alien Cookies x Colombian/Starfighter cross. Produces very frosty, dense buds on a medium-height plant. Can be finicky, so a stable climate and careful feeding pay off.', 'MAC (Miracle Alien Cookies) od Capulatora, kříženec Alien Cookies s Colombian/Starfighter. Na středně vysoké rostlině tvoří velmi ojíněné, husté palice. Bývá citlivější, vyplatí se stabilní klima a opatrné hnojení.'),
('mango-kush', 'Mango Kush', 'Various', 'indica', 'photo', 8, 9, 'Kush-based indica known for a sweet mango-like aroma. Plants stay short and sturdy with broad leaves and dense, compact buds, which suits small indoor spaces. Flowering takes about eight to nine weeks.', 'Indika z linie Kush známá sladkou vůní připomínající mango. Rostliny zůstávají nízké a pevné se širokými listy a hustými, kompaktními palicemi, takže se hodí do malých vnitřních prostor. Kvetení trvá asi osm až devět týdnů.'),
('master-kush', 'Master Kush', 'Various', 'indica', 'photo', 8, 9, 'Classic indica built from two Hindu Kush landraces, popularised in Amsterdam. Plants are short and bushy with broad leaves, dense resinous buds and an earthy, hashy aroma; it is regarded as easy to grow.', 'Klasická indika ze dvou krajových odrůd Hindu Kush, proslavená v Amsterdamu. Rostliny jsou nízké a keřovité se širokými listy, hustými pryskyřičnými palicemi a zemitou hašišovou vůní; považuje se za snadnou na pěstování.'),
('maui-wowie', 'Maui Wowie', 'Landrace', 'sativa', 'photo', 9, 11, 'Maui Wowie is a classic Hawaiian sativa associated with the island of Maui. It thrives in warm, humid climates and grows tall with a light, airy structure. Indoors it needs space and good lighting to fill out.', 'Maui Wowie je klasická havajská sativa spojovaná s ostrovem Maui. Daří se jí v teplém a vlhkém klimatu, roste vysoko a má lehkou, vzdušnou stavbu. Uvnitř potřebuje prostor a dobré světlo, aby palice zhutněly.'),
('mazar', 'Mazar', 'Dutch Passion', 'indica', 'photo', 8, 9, 'Mazar from Dutch Passion crosses an Afghan Mazar-i-Sharif line with Skunk #1. Plants are sturdy and indica-dominant with heavy, resinous colas. It is known as a reliable, high-yielding plant that tolerates beginner mistakes well.', 'Mazar od Dutch Passion kříží afghánskou linii Mazar-i-Sharif se Skunk #1. Rostliny jsou robustní, indikově dominantní a tvoří těžké, pryskyřičné palice. Je známá jako spolehlivá a výnosná odrůda, která dobře snáší chyby začátečníků.'),
('mendo-breath', 'Mendo Breath', 'Gage Green Genetics', 'indica', 'photo', 8, 9, 'Indica from Gage Green Genetics combining OG Kush Breath and Mendo Montage. Compact plants with dense, often purple-tinged buds. Responds well to topping in small spaces.', 'Indika od Gage Green Genetics spojující OG Kush Breath a Mendo Montage. Kompaktní rostliny s hustými, často nafialovělými palicemi. V malých prostorách dobře reaguje na zaštipování.'),
('mexican-sativa', 'Mexican Sativa', 'Landrace', 'sativa', 'photo', 10, 14, 'Umbrella name for traditional Mexican sativa landraces such as the old Oaxacan and Guerrero types. Tall, lanky plants with narrow leaves and airy buds are best suited to warm outdoor climates and long seasons. Flowering commonly lasts ten to fourteen weeks.', 'Souhrnný název pro tradiční mexické sativové krajové odrůdy, například staré typy z Oaxacy a Guerrera. Vysoké, vytáhlé rostliny s úzkými listy a vzdušnými palicemi se nejlépe hodí do teplého klimatu s dlouhou sezónou. Kvetení běžně trvá deset až čtrnáct týdnů.'),
('mimosa', 'Mimosa', 'Symbiotic Genetics', 'sativa', 'photo', 8, 10, 'Sativa-leaning cross of Clementine and Purple Punch with a bright citrus aroma. Plants are vigorous with moderate stretch and produce colourful, resinous buds with good yields.', 'Kříženec Clementine a Purple Punch s převahou sativy a svěží citrusovou vůní. Rostliny jsou vitální se středním natahováním a tvoří barevné, pryskyřičné palice s dobrým výnosem.'),
('moby-dick', 'Moby Dick', 'Dinafem', 'sativa', 'photo', 9, 10, 'Moby Dick is a Dinafem sativa-dominant cross of Haze and White Widow. It is a large, vigorous plant capable of big yields, especially outdoors. Plan for significant stretch and support the heavy colas.', 'Moby Dick je odrůda od Dinafem s převahou sativy z křížení Haze a White Widow. Je to velká, vitální rostlina schopná vysokých výnosů, zejména venku. Počítej s výrazným natažením a podepři těžké vrcholy.'),
('mothers-finest', 'Mother''s Finest', 'Sensi Seeds', 'sativa', 'photo', 8, 10, 'Mother''s Finest is a sativa-dominant, Haze-heavy strain from Sensi Seeds, related to Jack Herer. Plants stretch considerably after the switch to flower, so start blooming early if height is limited. Indica-leaning phenotypes can finish closer to eight weeks.', 'Mother''s Finest je sativně dominantní odrůda se silným podílem Haze od Sensi Seeds, příbuzná s Jack Herer. Po přepnutí na květ se výrazně natahuje, takže při omezené výšce přepněte dříve. Indikovější fenotypy mohou dozrát blíže k osmi týdnům.'),
('nevilles-haze', 'Nevilles Haze', 'Mr. Nice Seeds', 'sativa', 'photo', 12, 16, 'Near-pure Haze associated with Neville Schoenmakers, now offered by Mr. Nice Seeds. Very tall, stretchy plants with an extremely long flowering period. Only practical with lots of space, patience and strong training.', 'Téměř čistý haze spojovaný s Nevillem Schoenmakersem, dnes v nabídce Mr. Nice Seeds. Velmi vysoké, natahující se rostliny s extrémně dlouhou dobou květu. Prakticky jen pro pěstitele s velkým prostorem, trpělivostí a důkladným tvarováním.'),
('northern-express', 'Northern Express', 'Various', 'indica', 'auto', 6, 8, 'Fast autoflowering indica built on Northern Lights-type genetics. Compact plants with a dominant main cola and dense buds finish quickly, making them practical for short outdoor seasons. The bloom phase lasts about six to eight weeks.', 'Rychlá samonakvétací indika postavená na genetice typu Northern Lights. Kompaktní rostliny s výraznou hlavní palicí a hustými květy dozrávají rychle, takže se hodí i pro krátkou venkovní sezónu. Fáze květu trvá zhruba šest až osm týdnů.'),
('og-kush-auto', 'OG Kush Auto', 'Various', 'hybrid', 'auto', 6, 8, 'Autoflowering version of OG Kush crossed with ruderalis. Plants stay compact and finish quickly while keeping the fuel, lemon and pine aroma of the OG line.', 'Samonakvétací verze OG Kush křížená s ruderalis. Rostliny zůstávají kompaktní a dozrávají rychle, přitom si drží palivovou, citronovou a borovicovou vůni linie OG.'),
('orange-bud', 'Orange Bud', 'Dutch Passion', 'hybrid', 'photo', 8, 9, 'Orange Bud is a Dutch Passion selection of Skunk #1, named for its orange-coloured pistils and citrus aroma. It is a robust, easy plant that does well indoors and in greenhouses. Buds are compact and evenly formed.', 'Orange Bud je selekce Skunk #1 od Dutch Passion, pojmenovaná podle oranžových blizen a citrusové vůně. Je to odolná a nenáročná rostlina, která se dobře daří uvnitř i ve skleníku. Palice jsou kompaktní a pravidelné.'),
('orange-sherbet', 'Orange Sherbet', 'Various', 'hybrid', 'photo', 8, 9, 'Orange Sherbet is a citrus-scented hybrid from the Sherbet family, offered by several breeders. Plants are medium-sized with good side branching and dense, colourful buds. It responds well to topping and an even canopy.', 'Orange Sherbet je hybrid s citrusovou vůní z rodiny Sherbet, který nabízí více šlechtitelů. Rostliny jsou středně velké, dobře se větví a tvoří husté, barevné palice. Dobře reaguje na zaštipování a rovnoměrný porost.'),
('oreoz', 'Oreoz', '3rd Coast Genetics', 'hybrid', 'photo', 8, 9, 'Cookies and Cream x Secret Weapon cross from 3rd Coast Genetics. Dense, dark, heavily frosted buds on a moderately compact plant. Keep humidity in check late in flower.', 'Kříženec Cookies and Cream x Secret Weapon od 3rd Coast Genetics. Husté, tmavé a silně ojíněné palice na středně kompaktní rostlině. V pozdním květu hlídejte vlhkost.'),
('original-glue', 'Original Glue', 'GG Strains', 'hybrid', 'photo', 8, 9, 'Original Glue is the renamed Gorilla Glue #4 (GG4), bred from Chem''s Sister, Sour Dubb and Chocolate Diesel. Vigorous plants stretch noticeably after the flip and produce chunky, extremely resinous buds with a strong diesel-earth aroma. Flowering takes about eight to nine weeks.', 'Original Glue je přejmenovaná Gorilla Glue #4 (GG4), vyšlechtěná z Chem''s Sister, Sour Dubb a Chocolate Diesel. Vitální rostliny se po přepnutí výrazně natahují a tvoří mohutné, mimořádně pryskyřičné palice se silnou vůní nafty a zeminy. Kvetení trvá asi osm až devět týdnů.'),
('panama-red', 'Panama Red', 'Landrace', 'sativa', 'photo', 11, 14, 'Panama Red is a legendary Panamanian landrace sativa popular in the 1960s and 70s. It grows tall and slender with a long flowering period and reddish pistils. It suits warm climates with long seasons best.', 'Panama Red je legendární panamská landrasová sativa oblíbená v 60. a 70. letech. Roste vysoko a štíhle, kvete dlouho a má načervenalé blizny. Nejlépe se jí daří v teplém klimatu s dlouhou sezónou.'),
('papaya', 'Papaya', 'Nirvana Seeds', 'indica', 'photo', 8, 9, 'Papaya from Nirvana Seeds is an indica-dominant cross of Citral #13 and Ice #2 with a tropical fruit aroma. Plants grow medium height with a strong main cola and solid yields. It is generally easy to grow indoors and outdoors in warm climates.', 'Papaya od Nirvana Seeds je indikově dominantní kříženec Citral #13 a Ice #2 s vůní tropického ovoce. Rostliny jsou středně vysoké se silnou hlavní palicí a solidním výnosem. Obecně se dobře pěstuje uvnitř i venku v teplém klimatu.'),
('peanut-butter-breath', 'Peanut Butter Breath', 'Thug Pug Genetics', 'hybrid', 'photo', 8, 9, 'Do-Si-Dos x Mendo Breath cross from Thug Pug Genetics with a nutty, earthy aroma. Medium-sized, fairly compact plants with dense buds. Suits indoor tents with topping or SCROG.', 'Kříženec Do-Si-Dos x Mendo Breath od Thug Pug Genetics s oříškovou, zemitou vůní. Středně velké, poměrně kompaktní rostliny s hustými palicemi. Hodí se do stanu se zaštipováním nebo SCROG.'),
('pennywise', 'Pennywise', 'TGA Subcool Seeds', 'hybrid', 'photo', 8, 9, 'Cross of Harlequin and Jack the Ripper from TGA Subcool, known for phenotypes with balanced CBD and THC. Plants are medium-sized and resinous with an earthy, lemony aroma; cannabinoid ratios vary between phenotypes. Flowering takes about eight to nine weeks.', 'Kříženec Harlequin a Jack the Ripper od TGA Subcool, známý fenotypy s vyrovnaným poměrem CBD a THC. Rostliny jsou středně velké a pryskyřičné se zemitě citronovou vůní; poměr kanabinoidů se mezi fenotypy liší. Kvetení trvá asi osm až devět týdnů.'),
('permanent-marker', 'Permanent Marker', 'Seed Junky Genetics', 'hybrid', 'photo', 8, 10, 'Recent hybrid from Biscotti, Jealousy and Sherbet lines, named for its sharp, chemical and floral smell. Plants are medium-sized with dense, frosty buds; strong odour control is advisable.', 'Novější hybrid z linií Biscotti, Jealousy a Sherbet, pojmenovaný podle ostré chemické a květinové vůně. Rostliny jsou středně velké s hustými, ojíněnými palicemi; doporučuje se účinná filtrace pachu.'),
('pineapple-chunk', 'Pineapple Chunk', 'Barney''s Farm', 'indica', 'photo', 8, 9, 'Pineapple Chunk is a Barney''s Farm indica-leaning strain from Pineapple, Skunk #1 and Cheese genetics. It grows bushy with large, chunky buds and a tropical, cheesy aroma. It is a productive and fairly easy plant.', 'Pineapple Chunk je odrůda od Barney''s Farm s převahou indiky z genetiky Pineapple, Skunk #1 a Cheese. Roste košatě, tvoří velké, masivní palice a má tropicko-sýrovou vůni. Je výnosná a poměrně nenáročná.'),
('pineapple-kush', 'Pineapple Kush', 'Various', 'hybrid', 'photo', 8, 9, 'Pineapple Kush is an indica-leaning hybrid with a sweet, tropical aroma, available from several breeders. Plants stay fairly compact with dense, resinous buds. It is a forgiving plant suited to indoor tents.', 'Pineapple Kush je spíše indikový hybrid se sladkou tropickou vůní, který nabízí více šlechtitelů. Rostliny zůstávají poměrně kompaktní s hustými, pryskyřičnými palicemi. Je to nenáročná odrůda vhodná do growboxu.'),
('pink-kush', 'Pink Kush', 'Various', 'indica', 'photo', 8, 9, 'Canadian indica-dominant Kush, originally a clone from the OG Kush family. Compact plants with dense buds that can show pinkish pistils. Benefits from good airflow and low humidity in late flower.', 'Kanadský převážně indický kush, původně klon z rodiny OG Kush. Kompaktní rostliny s hustými palicemi, na kterých mohou být narůžovělé blizny. V pozdním květu prospívá dobré proudění vzduchu a nízká vlhkost.'),
('platinum-og', 'Platinum OG', 'Various', 'indica', 'photo', 8, 9, 'Indica-leaning OG hybrid named for its heavy, silvery trichome coverage. Plants stay medium height with dense buds and an earthy-pine OG aroma; support helps late in bloom. Flowering takes roughly eight to nine weeks.', 'Převážně indický OG hybrid pojmenovaný podle hustého stříbřitého pokryvu trichomů. Rostliny dorůstají střední výšky s hustými palicemi a zemitě borovicovou OG vůní; na konci květu pomůže opora. Kvetení trvá zhruba osm až devět týdnů.'),
('power-plant', 'Power Plant', 'Dutch Passion', 'sativa', 'photo', 7, 8, 'Power Plant is a Dutch Passion sativa developed from South African genetics. It grows tall with long, uniform colas and finishes relatively fast for a sativa. It is well suited to sea-of-green style indoor growing.', 'Power Plant je sativa od Dutch Passion vyvinutá z jihoafrické genetiky. Roste vysoko s dlouhými, vyrovnanými vrcholy a na sativu dozrává poměrně rychle. Dobře se hodí pro indoor pěstování metodou SOG.'),
('purple-haze-auto', 'Purple Haze Auto', 'Various', 'sativa', 'auto', 7, 9, 'Purple Haze Auto is an autoflowering version of the sativa-dominant Purple Haze, offered by several seed banks. Plants are taller than many autos and may show purple tones in cooler nights. Total time from seed is around 10 to 12 weeks.', 'Purple Haze Auto je samonakvétací verze sativně dominantní Purple Haze od více semenáren. Rostliny bývají vyšší než mnohé automatky a při chladnějších nocích mohou zfialovět. Celková doba od semínka je kolem 10 až 12 týdnů.'),
('purple-kush-auto', 'Purple Kush Auto', 'Various', 'indica', 'auto', 6, 8, 'Autoflowering version of Purple Kush offered by several seedbanks. Short, compact plants that may turn purple, especially with cooler nights. A good fit for small spaces and balconies.', 'Samonakvétací verze Purple Kush od více semenáren. Nízké, kompaktní rostliny, které mohou fialovět, hlavně při chladnějších nocích. Dobře se hodí do malých prostor i na balkon.'),
('purple-punch', 'Purple Punch', 'Supernova Gardens', 'indica', 'photo', 8, 9, 'Indica-dominant cross of Larry OG and Granddaddy Purple. Short, bushy plants produce dense buds that readily turn purple in cooler late-bloom temperatures, with a sweet grape-candy aroma. Flowering takes about eight to nine weeks.', 'Převážně indický kříženec Larry OG a Granddaddy Purple. Nízké, košaté rostliny tvoří husté palice, které při chladnějších teplotách na konci květu snadno fialoví, a voní sladce po hroznových bonbónech. Kvetení trvá asi osm až devět týdnů.'),
('purple-trainwreck', 'Purple Trainwreck', 'Various', 'sativa', 'photo', 9, 10, 'Purple-hued relative of Trainwreck, commonly listed as Trainwreck x Mendocino Purps. Plants grow tall with some stretch and produce spicy, sweet buds that can colour late in flower.', 'Fialově zbarvený příbuzný Trainwrecku, obvykle uváděný jako Trainwreck x Mendocino Purps. Rostliny rostou vysoké s určitým natahováním a tvoří kořeněně sladké palice, které mohou ke konci květu barvit.'),
('quick-one', 'Quick One', 'Royal Queen Seeds', 'hybrid', 'auto', 5, 6, 'Quick One is a Royal Queen Seeds autoflower built for speed and small size. Plants stay short and are ready in a very short time from seed. It is suited to balconies, small tents and short outdoor seasons.', 'Quick One je samonakvétací odrůda od Royal Queen Seeds stavěná na rychlost a malý vzrůst. Rostliny zůstávají nízké a ze semínka jsou hotové za velmi krátkou dobu. Hodí se na balkon, do malých growboxů a na krátkou venkovní sezónu.'),
('rainbow-belts', 'Rainbow Belts', 'Archive Seed Bank', 'hybrid', 'photo', 8, 9, 'Rainbow Belts from Archive Seed Bank crosses Zkittlez with Moonbow and has a sweet, candy-like aroma. Plants are medium-sized, indica-leaning and produce dense, frosty buds that can show purple hues. Training helps fill the canopy evenly.', 'Rainbow Belts od Archive Seed Bank je kříženec Zkittlez a Moonbow se sladkou, bonbonovou vůní. Rostliny jsou středně velké, spíše indikové a tvoří husté, ojíněné palice, které mohou mít fialový nádech. Tvarování pomáhá vyplnit porost rovnoměrně.'),
('ringos-gift', 'Ringo''s Gift', 'Southern Humboldt Seed Collective', 'hybrid', 'photo', 8, 10, 'High-CBD hybrid named after Lawrence Ringo, combining Harle-Tsu and ACDC lines. Phenotypes vary in cannabinoid ratio, so lab testing or a selected clone helps. Moderate vigour and a medium-height frame.', 'Hybrid s vysokým obsahem CBD pojmenovaný po Lawrencovi Ringovi, spojující linie Harle-Tsu a ACDC. Fenotypy se liší poměrem kanabinoidů, pomůže laboratorní test nebo vybraný klon. Středně vitální rostlina střední výšky.'),
('romulan', 'Romulan', 'Various', 'indica', 'photo', 7, 9, 'Classic British Columbia indica with a reputation for very resinous, compact plants. Short internodes and dense buds suit small indoor spaces, though airflow should be kept high to avoid mould. Flowering takes about seven to nine weeks.', 'Klasická indika z Britské Kolumbie s pověstí velmi pryskyřičných, kompaktních rostlin. Krátká internodia a husté palice se hodí do malých vnitřních prostor, ale kvůli plísni je potřeba udržovat silné proudění vzduchu. Kvetení trvá asi sedm až devět týdnů.'),
('royal-dwarf', 'Royal Dwarf', 'Royal Queen Seeds', 'hybrid', 'auto', 5, 7, 'Compact autoflower based on Skunk genetics, bred for small spaces. Plants usually stay very short and finish quickly from seed, giving modest yields of dense buds.', 'Kompaktní samonakvétačka na genetice Skunk, šlechtěná pro malé prostory. Rostliny obvykle zůstávají velmi nízké a dozrávají rychle, s menším výnosem hustých palic.'),
('royal-gorilla', 'Royal Gorilla', 'Royal Queen Seeds', 'hybrid', 'photo', 8, 9, 'Royal Gorilla is Royal Queen Seeds'' version of the Gorilla Glue line from Sour Dubb, Chem Sister and Chocolate Diesel. It is vigorous with strong branching and very resinous buds. Training and support help with the heavy side branches.', 'Royal Gorilla je verze linie Gorilla Glue od Royal Queen Seeds ze Sour Dubb, Chem Sister a Chocolate Diesel. Je vitální, silně se větví a tvoří velmi pryskyřičnaté palice. Tvarování a opora pomohou s těžkými bočními větvemi.'),
('royal-highness', 'Royal Highness', 'Royal Queen Seeds', 'hybrid', 'photo', 8, 9, 'Royal Highness is a sativa-leaning hybrid from Royal Queen Seeds bred for a balanced CBD-to-THC chemotype. Plants grow vigorously with long side branches and medium-density buds. Training or SCROG keeps the stretch under control indoors.', 'Royal Highness je spíše sativní hybrid od Royal Queen Seeds vyšlechtěný pro vyvážený poměr CBD a THC. Rostliny rostou bujně s dlouhými bočními větvemi a palicemi střední hustoty. Tvarování nebo SCROG pomáhá uvnitř zvládnout natahování.'),
('sensi-star', 'Sensi Star', 'Paradise Seeds', 'indica', 'photo', 8, 9, 'Indica-dominant Dutch classic from Paradise Seeds. Compact, sturdy plants with short internodes produce very dense, heavily frosted buds, making it well suited to small indoor spaces. Finishes in about eight to nine weeks of bloom.', 'Převážně indická holandská klasika od Paradise Seeds. Kompaktní a pevné rostliny s krátkými internodii tvoří velmi husté, silně ojíněné palice, takže se hodí i do malých vnitřních prostorů. Dozrává zhruba za osm až devět týdnů květu.'),
('sfv-og', 'SFV OG', 'Various', 'hybrid', 'photo', 8, 9, 'OG Kush cut from the San Fernando Valley, also available as seed versions. Medium height with dense, resinous buds and the typical fuel-and-pine OG aroma. OG cuts can be sensitive to overfeeding.', 'Klon OG Kush ze San Fernando Valley, dostupný i v semínkových verzích. Středně vysoká rostlina s hustými pryskyřičnými palicemi a typickou OG vůní nafty a borovice. OG klony bývají citlivé na přehnojení.'),
('sherbet', 'Sherbet', 'Sherbinski', 'indica', 'photo', 8, 9, 'Short name for Sunset Sherbet, a Girl Scout Cookies descendant. Medium-sized plants with dense, often purple buds and a sweet, fruity and creamy aroma; yields are moderate.', 'Zkrácený název pro Sunset Sherbet, potomka Girl Scout Cookies. Středně velké rostliny s hustými, často fialovými palicemi a sladkou ovocně krémovou vůní; výnos je střední.'),
('shiva-skunk', 'Shiva Skunk', 'Sensi Seeds', 'indica', 'photo', 6, 8, 'Shiva Skunk is a Sensi Seeds indica from Northern Lights #5 and Skunk #1. It grows compact with a strong central cola and finishes quickly. A reliable and fairly easy plant for indoor growing.', 'Shiva Skunk je indika od Sensi Seeds z Northern Lights #5 a Skunk #1. Roste kompaktně se silným hlavním vrcholem a rychle dozrává. Je to spolehlivá a poměrně nenáročná rostlina pro indoor pěstování.'),
('silver-haze', 'Silver Haze', 'Various', 'sativa', 'photo', 10, 12, 'Silver Haze is a sativa-dominant Haze line known for long, frosty, silver-looking colas. Plants stretch strongly in flower and need a long bloom period. It suits growers with enough height and patience.', 'Silver Haze je sativně dominantní linie Haze známá dlouhými, ojíněnými, stříbřitě vyhlížejícími palicemi. V kvetení se silně natahuje a potřebuje dlouhou dobu kvetení. Hodí se pro pěstitele s dostatkem výšky a trpělivosti.'),
('skunk-auto', 'Skunk Auto', 'Various', 'hybrid', 'auto', 6, 8, 'Autoflowering version of the Skunk #1 line, sold by many seedbanks. Robust, fast and forgiving, with a strong skunky smell. A popular choice for first grows.', 'Samonakvétací verze linie Skunk #1, kterou prodává řada semenáren. Odolná, rychlá a shovívavá, se silným skunkovým pachem. Oblíbená volba na první pěstování.'),
('skywalker-og', 'Skywalker OG', 'Various', 'indica', 'photo', 8, 10, 'Indica-dominant California OG cross combining Skywalker with OG Kush. Plants show classic OG structure with moderate stretch and dense, resin-heavy buds that benefit from support and good airflow late in bloom. Typically finishes in eight to ten weeks.', 'Převážně indický kalifornský OG kříženec spojující Skywalker s OG Kush. Rostliny mají typickou OG stavbu se středním natahováním a husté, pryskyřicí obalené palice, kterým na konci květu prospěje opora a dobré proudění vzduchu. Obvykle dozrává za osm až deset týdnů.'),
('slurricane', 'Slurricane', 'In House Genetics', 'indica', 'photo', 8, 9, 'Indica-dominant cross of Do-Si-Dos and Purple Punch. Compact plants with very frosty, dense buds that can show purple hues; a sweet grape and berry aroma dominates.', 'Kříženec Do-Si-Dos a Purple Punch s převahou indiky. Kompaktní rostliny s velmi ojíněnými, hustými palicemi, které mohou fialovět; převládá sladká vůně hroznů a bobulí.'),
('somango', 'Somango', 'Soma Seeds', 'hybrid', 'photo', 8, 9, 'Somango is a Soma Seeds hybrid of Jack Herer and Super Skunk with a sweet mango aroma. Plants are medium-sized and productive with dense buds. It does well indoors and in sheltered outdoor spots.', 'Somango je hybrid od Soma Seeds z Jack Herer a Super Skunk se sladkou mangovou vůní. Rostliny jsou středně velké a výnosné, s hustými palicemi. Dobře se mu daří uvnitř i na chráněném místě venku.'),
('sour-cookies', 'Sour Cookies', 'Various', 'hybrid', 'photo', 9, 10, 'Sour Cookies is a hybrid of Sour Diesel and Girl Scout Cookies, offered by several breeders. Plants show moderate stretch and build resinous buds with a fuel and sweet dough aroma. Topping and a light trellis help support the colas.', 'Sour Cookies je hybrid ze Sour Diesel a Girl Scout Cookies, který nabízí více šlechtitelů. Rostliny se mírně natahují a tvoří pryskyřičné palice s vůní nafty a sladkého těsta. Zaštipování a lehká síť pomáhají palice podepřít.'),
('sour-diesel-auto', 'Sour Diesel Auto', 'Various', 'sativa', 'auto', 7, 9, 'Autoflowering version of Sour Diesel offered by several seedbanks. Taller and lankier than most autos, with a pungent diesel aroma. Odour control and gentle LST are recommended.', 'Samonakvétací verze Sour Diesel od více semenáren. Na autoflower vyšší a vytáhlejší, s pronikavou vůní nafty. Doporučuje se filtrace pachu a jemné LST.'),
('sour-kush', 'Sour Kush', 'DNA Genetics', 'hybrid', 'photo', 8, 9, 'Hybrid of Sour Diesel and OG Kush with a pungent fuel-and-pine aroma. Plants stretch moderately and form dense, resinous colas; strong odour control is recommended indoors. Flowering usually takes eight to nine weeks.', 'Hybrid Sour Diesel a OG Kush s pronikavou vůní nafty a borovice. Rostliny se středně natahují a tvoří husté pryskyřičné palice; při pěstování uvnitř je nutná dobrá filtrace pachu. Kvetení obvykle trvá osm až devět týdnů.'),
('sour-tangie', 'Sour Tangie', 'DNA Genetics', 'sativa', 'photo', 9, 11, 'Sativa-dominant cross of Sour Diesel and Tangie with a mix of fuel and tangerine aromas. Plants stretch considerably, so topping or low-stress training is useful indoors.', 'Kříženec Sour Diesel a Tangie s převahou sativy, ve vůni kombinuje palivo a mandarinku. Rostliny se značně natahují, proto se uvnitř vyplatí zaštípnutí nebo šetrné ohýbání (LST).'),
('speed-devil', 'Speed Devil', 'Sweet Seeds', 'hybrid', 'auto', 5, 6, 'Speed Devil is a fast Sweet Seeds autoflower selected for a very short life cycle. Plants stay compact and form a dominant central cola. It suits small spaces and quick outdoor runs.', 'Speed Devil je rychlá samonakvétací odrůda od Sweet Seeds vybraná na velmi krátký životní cyklus. Rostliny zůstávají kompaktní a tvoří výrazný hlavní vrchol. Hodí se do malých prostor a na rychlé venkovní pěstování.'),
('stardawg', 'Stardawg', 'Top Dawg Seeds', 'hybrid', 'photo', 9, 10, 'Stardawg from Top Dawg Seeds crosses Chemdawg 4 with Tres Dawg. It is a sativa-leaning hybrid with noticeable stretch and very resinous, spear-shaped colas with a sharp diesel aroma. Odour control is recommended indoors.', 'Stardawg od Top Dawg Seeds je kříženec Chemdawg 4 a Tres Dawg. Jde o spíše sativní hybrid s výrazným natahováním a velmi pryskyřičnými, kopinatými palicemi s ostrou naftovou vůní. Uvnitř se doporučuje uhlíkový filtr.'),
('strawberry-banana', 'Strawberry Banana', 'Crockett Family Farms', 'hybrid', 'photo', 8, 9, 'Indica-leaning hybrid from Crockett Family Farms with a sweet, fruity aroma. Medium height and very resinous buds. Defoliation and airflow help with its dense canopy.', 'Indikou laděný hybrid od Crockett Family Farms se sladkou ovocnou vůní. Středně vysoká rostlina s velmi pryskyřičnými palicemi. U hustého porostu pomůže odlistění a proudění vzduchu.'),
('strawberry-kush', 'Strawberry Kush', 'Various', 'hybrid', 'photo', 8, 9, 'Kush-based hybrid named for its sweet strawberry aroma. Plants grow to medium height with dense, resinous buds and respond well to topping and low-stress training. Flowering takes about eight to nine weeks.', 'Hybrid z linie Kush pojmenovaný podle sladké jahodové vůně. Rostliny dorůstají střední výšky s hustými pryskyřičnými palicemi a dobře reagují na zaštipování i jemný trénink. Kvetení trvá asi osm až devět týdnů.'),
('sugar-black-rose', 'Sugar Black Rose', 'Delicious Seeds', 'indica', 'photo', 8, 9, 'Indica-dominant hybrid known for dark, almost black-purple colouring in some phenotypes and a sweet, earthy aroma. Plants are medium-sized and productive with dense buds.', 'Hybrid s převahou indiky, známý tmavým, téměř černofialovým zbarvením některých fenotypů a sladce zemitou vůní. Rostliny jsou středně velké a výnosné s hustými palicemi.'),
('super-glue', 'Super Glue', 'Various', 'hybrid', 'photo', 8, 9, 'Super Glue is an indica-leaning hybrid named for its very sticky, resin-heavy buds. Plants are medium-sized and sturdy with dense colas. Good airflow helps prevent mould in the tight buds.', 'Super Glue je hybrid s převahou indiky pojmenovaný podle velmi lepkavých, pryskyřičnatých palic. Rostliny jsou středně velké a pevné, s hustými vrcholy. Dobré proudění vzduchu pomáhá předejít plísni v hustých palicích.'),
('super-silver-haze-auto', 'Super Silver Haze Auto', 'Various', 'sativa', 'auto', 7, 9, 'Super Silver Haze Auto is an autoflowering version of the classic Super Silver Haze, available from several seed banks. It keeps the Haze aroma and airy, elongated buds in a shorter plant. Expect around 10 to 12 weeks from seed.', 'Super Silver Haze Auto je samonakvétací verze klasické Super Silver Haze od více semenáren. Zachovává vůni Haze a vzdušné, protáhlé palice v nižší rostlině. Počítejte zhruba s 10 až 12 týdny od semínka.'),
('sweet-tooth', 'Sweet Tooth', 'Barney''s Farm', 'indica', 'photo', 8, 9, 'Indica-dominant line known from Sweet Tooth #3, with a sweet, candy-like aroma. Compact to medium plants with dense buds. Straightforward to grow indoors.', 'Převážně indická linie známá z výběru Sweet Tooth #3, se sladkou vůní připomínající bonbony. Kompaktní až středně velké rostliny s hustými palicemi. Uvnitř se pěstuje bez větších potíží.'),
('tahoe-og', 'Tahoe OG', 'Various', 'indica', 'photo', 8, 9, 'Indica-leaning California OG Kush phenotype from the Lake Tahoe area. Plants show OG structure with moderate stretch and dense, lemon-fuel buds that finish relatively quickly for an OG. Flowering takes about eight to nine weeks.', 'Převážně indický kalifornský fenotyp OG Kush z oblasti jezera Tahoe. Rostliny mají OG stavbu se středním natahováním a husté palice s vůní citronu a nafty, na OG dozrávají poměrně rychle. Kvetení trvá asi osm až devět týdnů.'),
('tangie', 'Tangie', 'DNA Genetics', 'sativa', 'photo', 9, 10, 'Sativa-dominant revival of the 1990s Tangerine Dream line with a strong tangerine aroma. Plants are tall and vigorous with sizeable yields; plan for stretch in early flower.', 'Sativou dominovaná obnova linie Tangerine Dream z 90. let se silnou mandarinkovou vůní. Rostliny jsou vysoké a vitální se slušným výnosem; počítejte s natažením na začátku květu.'),
('thai', 'Thai', 'Landrace', 'sativa', 'photo', 12, 16, 'Thai is a landrace sativa from Thailand and the source of many classic hybrids such as Haze. Plants grow very tall and airy with thin leaves and a long flowering period. It is best suited to warm climates or experienced indoor growers.', 'Thai je landrasová sativa z Thajska a zdroj mnoha klasických hybridů, například Haze. Rostliny rostou velmi vysoko a vzdušně, mají úzké listy a dlouhou dobu květu. Nejlépe se hodí do teplého klimatu nebo pro zkušené pěstitele uvnitř.'),
('the-white', 'The White', 'Various', 'hybrid', 'photo', 8, 9, 'The White is an indica-leaning hybrid that circulated mainly as a clone and is named for its extremely heavy trichome coverage. Plants are medium-sized with dense, compact buds. It has been widely used as a parent in OG-type crosses.', 'The White je spíše indikový hybrid, který se šířil hlavně jako klon a jméno dostal podle mimořádně hustého pokryvu trichomů. Rostliny jsou středně velké s hustými, kompaktními palicemi. Často se používá jako rodič v křížencích typu OG.'),
('trainwreck-auto', 'Trainwreck Auto', 'Various', 'sativa', 'auto', 7, 9, 'Autoflowering version of Trainwreck offered by several seedbanks. Lively growth with a sharp, piney-citrus aroma. Gives the best results with strong light and no transplanting.', 'Samonakvétací verze Trainwrecku od více semenáren. Živý růst a ostrá vůně borovice a citrusů. Nejlepších výsledků dosahuje při silném světle a bez přesazování.'),
('triangle-kush', 'Triangle Kush', 'Various', 'indica', 'photo', 8, 10, 'Florida-born Kush named after the Jacksonville-Miami-Tampa triangle and a parent of many modern hybrids. Plants have classic Kush structure with dense, resinous buds and a gassy, earthy aroma. Flowering takes about eight to ten weeks.', 'Kush pocházející z Floridy, pojmenovaný podle trojúhelníku Jacksonville-Miami-Tampa, a rodič mnoha moderních hybridů. Rostliny mají klasickou kushovou stavbu s hustými pryskyřičnými palicemi a benzínovo-zemitou vůní. Kvetení trvá asi osm až deset týdnů.'),
('tropical-punch', 'Tropical Punch', 'Sweet Seeds', 'sativa', 'photo', 8, 9, 'Sativa-dominant hybrid with a citrus and tropical fruit aroma. Plants are vigorous with moderate stretch and form long, fairly dense colas; training helps keep the canopy even.', 'Hybrid s převahou sativy s citrusovou a tropicky ovocnou vůní. Rostliny jsou vitální se středním natahováním a tvoří dlouhé, poměrně husté vrcholy; tvarování pomáhá udržet rovný porost.'),
('tropicana-cookies', 'Tropicana Cookies', 'Oni Seed Co.', 'sativa', 'photo', 9, 10, 'Tropicana Cookies is an Oni Seed Co. cross of Girl Scout Cookies and Tangie with a strong citrus aroma. Plants often show purple foliage and buds with bright orange pistils. It responds well to topping and training.', 'Tropicana Cookies je křížení Girl Scout Cookies a Tangie od Oni Seed Co. s výraznou citrusovou vůní. Rostliny mají často fialové listy i palice s jasně oranžovými bliznami. Dobře reaguje na zaštipování a tvarování.'),
('tutankhamon', 'Tutankhamon', 'Pyramid Seeds', 'hybrid', 'photo', 8, 10, 'Tutankhamon is a hybrid from the Spanish breeder Pyramid Seeds. Growers report vigorous plants with good branching and resinous buds. Reported flowering times vary between phenotypes, so watch the trichomes rather than the calendar.', 'Tutankhamon je hybrid od španělského šlechtitele Pyramid Seeds. Pěstitelé popisují bujné rostliny s dobrým větvením a pryskyřičnými palicemi. Uváděná doba kvetení se mezi fenotypy liší, proto sledujte spíše trichomy než kalendář.'),
('vanilla-kush', 'Vanilla Kush', 'Barney''s Farm', 'indica', 'photo', 8, 10, 'Indica-dominant Kush from Barney''s Farm with a sweet vanilla and floral aroma. Plants stay compact with dense buds and moderate stretch, suiting indoor tents. Flowering takes roughly eight to ten weeks.', 'Převážně indický Kush od Barney''s Farm se sladkou vanilkovou a květinovou vůní. Rostliny zůstávají kompaktní s hustými palicemi a mírným natahováním, takže se hodí do growboxu. Kvetení trvá zhruba osm až deset týdnů.'),
('venom-og', 'Venom OG', 'Rare Dankness', 'indica', 'photo', 8, 10, 'Indica-leaning OG hybrid of Poison OG and Rare Dankness #1. Plants are sturdy and medium-sized with dense, resinous buds and a sweet fuel and berry aroma.', 'OG hybrid s převahou indiky z Poison OG a Rare Dankness #1. Rostliny jsou statné a středně velké s hustými pryskyřičnými palicemi a sladkou palivovo-bobulovou vůní.'),
('wappa', 'Wappa', 'Paradise Seeds', 'indica', 'photo', 7, 8, 'Wappa is a compact, indica-dominant Paradise Seeds strain with a sweet, fruity aroma. It grows bushy with dense buds and finishes fairly quickly. It is well suited to small indoor spaces.', 'Wappa je kompaktní odrůda od Paradise Seeds s převahou indiky a sladce ovocnou vůní. Roste košatě s hustými palicemi a dozrává poměrně rychle. Dobře se hodí do malých indoor prostor.'),
('wedding-cake-auto', 'Wedding Cake Auto', 'Various', 'hybrid', 'auto', 7, 8, 'Wedding Cake Auto is an autoflowering version of the indica-leaning Wedding Cake, sold by several seed banks. Plants are compact with dense, frosty buds. Total time from seed is usually about 10 weeks.', 'Wedding Cake Auto je samonakvétací verze spíše indikové Wedding Cake od více semenáren. Rostliny jsou kompaktní s hustými, ojíněnými palicemi. Celková doba od semínka bývá zhruba 10 týdnů.'),
('white-choco', 'White Choco', 'Paradise Seeds', 'indica', 'photo', 8, 9, 'Indica-dominant hybrid from Paradise Seeds with a chocolatey, earthy aroma. Compact plants with frosty buds that suit indoor tents. Fairly easy to keep in shape.', 'Převážně indický hybrid od Paradise Seeds s čokoládovou, zemitou vůní. Kompaktní rostliny s ojíněnými palicemi, vhodné do stanu. Poměrně snadno se udržuje ve tvaru.'),
('white-fire-og', 'White Fire OG', 'Various', 'hybrid', 'photo', 9, 10, 'Also known as WiFi OG, a cross of Fire OG and The White. Plants stretch noticeably and build long, heavily frosted colas with a fuel-and-earth aroma; plan for support and odour control. Flowering takes about nine to ten weeks.', 'Známá také jako WiFi OG, kříženec Fire OG a The White. Rostliny se výrazně natahují a tvoří dlouhé, silně ojíněné palice s vůní nafty a zeminy; počítejte s oporou a filtrací pachu. Kvetení trvá asi devět až deset týdnů.'),
('white-russian', 'White Russian', 'Serious Seeds', 'hybrid', 'photo', 8, 9, 'Cross of AK-47 and White Widow, noted for an extremely heavy trichome cover. Medium-sized plants with compact buds and a manageable stretch; suitable for indoor growing.', 'Kříženec AK-47 a White Widow, známý mimořádně hustým povlakem trichomů. Středně velké rostliny s kompaktními palicemi a zvládnutelným natahováním; vhodné pro pěstování uvnitř.'),
('white-widow-auto', 'White Widow Auto', 'Various', 'hybrid', 'auto', 6, 7, 'White Widow Auto is the autoflowering version of the classic White Widow, offered by many breeders. Plants stay compact and produce frosty, resin-covered buds without a light-schedule change. It is a forgiving option for beginners.', 'White Widow Auto je samonakvétací verze klasické White Widow, kterou nabízí řada šlechtitelů. Rostliny zůstávají kompaktní a tvoří ojíněné, pryskyřicí pokryté palice bez nutnosti měnit světelný režim. Je to tolerantní volba pro začátečníky.'),
('xj-13', 'XJ-13', 'Jinxproof Genetics', 'sativa', 'photo', 9, 10, 'Sativa-dominant Jack Herer x G13 Haze cross from Jinxproof Genetics. Tall, stretchy plants with long colas and a citrus-pine aroma. Training and extra headroom are recommended.', 'Sativou dominovaný kříženec Jack Herer x G13 Haze od Jinxproof Genetics. Vysoké, natahující se rostliny s dlouhými palicemi a vůní citrusů a borovice. Doporučuje se tvarování a více místa na výšku.'),
('zkittlez-auto', 'Zkittlez Auto', 'Various', 'indica', 'auto', 7, 8, 'Autoflowering version of the candy-sweet Zkittlez. Compact plants with dense, often colourful buds suit small tents and balconies. The bloom phase lasts about seven to eight weeks.', 'Samonakvétací verze sladké odrůdy Zkittlez. Kompaktní rostliny s hustými, často barevnými palicemi se hodí do malých growboxů i na balkon. Fáze květu trvá zhruba sedm až osm týdnů.')
